(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["477"] = {"atoms": {"477.1": {"x": [[1, "10)\rباب الكلام في الإمامة\rإن قال قائل: ما الدليل على إمامة أبي بكر رضي الله عنه؟ قيل له: الدليل على ذلك أنا وجدنا الناس على ثلاثة أصناف: قائلين يقولون بإمامة على بعد الرسول صلى الله عليه، وقائلين يقولون بإمامة العباس رضي الله عنه، [وقائلين يقولون بإمامة الصديق رضي الله عنه]. ورأينا عليا والعباس قد بايعاه وانقادا لأمره في كافة المسلمين وإن كان قد توقف عن البيعة متوقفون وقتا ما فقد أطبقوا على البيعة له والانقياد لإمامته والكون تحت رايته واتباع أمره، وقالوا له: يا خليفة رسول الله، صلى الله عليه، ولا يجوز أن تجمع الأمة على خطأ. ولا يجوز لمدع أ، يدعى أن باطن على والعباس بخلاف ما أظهراه، ولو جاز ذلك لم يجز لنا أن نقضي على صحة إجماع من الأمة على شيء [لأنا] لا نأمن أن يكون باطن بعض الأمة خلاف ظاهرهم. فلما كان بما يظهر من الأمة من الاتفاق قد يعلم به الإجماع ولا يلتفت إلى دعوى من ادعى الباطن وكان مدعى "], [17, "بسم الله الرحمن الرحيم\rوبه نستعين\rالحمد لله ذي الجود والثناء، والمجد والسناء، والعز والكبرياء؛ أحمده على سوابغ النعم وجزيل العطاء، وأشهد أن لا إله إلا الله وحده لا شريك له عدة اللقاء، وأشهد أن محمدا عبده ورسوله خاتم الأنبياء.\rأما بعد؛ فإنك سألتني أن أصنف لك كتابا مختصرا أبين فيه جملا توضح الحق وتدمغ الباطل، فرأيت إسعافك بذلك، [رزقك] الله الخيرات، وأعانك على الخير والمطلوبات.\r(1)\r[الله وصفاته]\r"]], "pg": [1, 17]}, "477.2": {"x": [[17, "مسالة\rإن سأل سائل فقال: ما الدليل على أن الخلق صانعا صنعه ومدبرا دبره؟ قيل [له] الدليل على ذلك أن الإنسان الذي هو في غاية "], [18, "الكمال والتمام، كان نطفة ثم علقة ثم لحما ودما [وعظما]، وقد علمنا أنه لم ينقل نفسه من حال إلى حال؛ لأنا نراه في حال كمال قوته وتمام عقله لا يقدر أن يحدث لنفسه سمعا ولا بصرا، ولا أن يخلق لنفسه جارحة. يدل ذلك على أنه في حال ضعفه ونقصانه عن فعل ذلك أجز، لأن ما قدر عليه في حال النقصان فهو في الكمال عليه أقدر، وما عجز عنه في حال الكمال فهو في حال النقصان عنه أعجز. ورأيناه طفلا ثم شابا ثم كهلا ثم شيخا، وقد علمنا أنه لم ينقل نفسه من حال الشباب إلى حال الكبر والهرم؛ لأن الإنسان لو جهد أن يزيل عن نفسه الكبر والهرم ويردها إلى حال الشباب لم يمكنه ذلك؛ فدل ما وصفنا على أنه ليس هو الذي ينقل نفسه في هذه الأحوال، وأن له ناقلا نقله من حال إلى حال ودبره على ما هو عليه، لأنه لا يجوز انتقاله من حال إلى حال بغير ناقل ولا مدبر. مما بين ذلك أن القطن لا يجوز أ، يتحول غزلا مفتولا، ثم ثوبا منسوجا، بغير ناسج ولا صانع ولا مدبر، ومن اتخذ قطنا ثم انتظر أن يصير غزلا مفتولا، ثم ثوبا منسوجا بغير صانع ولا ناسج كان عن معقول خارجا، وفي الجهل والجا. وكذلك من قصد إلى برية لم يجد فيها قصرا مبنيا فانتظر أن يتحول الطين إلى حالة الآجر، وينتضد بعضه على بعض، بغير صانع ولا بان، كان جاهلا. وإذا كان تحول النطفة علقة، "], [19, "ثم مضغة، ثم لحما ودما وعظما، أعظم في الأعجوبة، كان أولى أن يدل على صانع صنع النطفة ونقلها من حال إلى حال. وقد قال الله تعالى: {أَفَرَأَيْتُمْ مَا تُمْنُونَ (58) أَأَنْتُمْ تَخْلُقُونَهُ أَمْ نَحْنُ الْخَالِقُونَ} [الفاتحة: 58، 59] فما استطاعوا أن يقولوا بحجة إنهم يخلقون ما يمنون مع تمنيهم الولد فلا يكون ومع كراهتهم له فيكون. وقد قال الله تعالى منبها لخلقه على وحدانيته: {وَفِي أَنْفُسِكُمْ أَفَلَا تُبْصِرُون} [الذاريات: 21] بين لهم عجزهم وفقرهم إلى صانع صنعهم ومدبر دبرهم.\rفإن قالوا: فما يؤمنكم أن تكون النطفة لم تزل قديمة؟ قيل لهم: لو كان ذلك كما ادعيتم لم يجز أن يلحقها الاعتمال والتأثير، ولا الانقلاب والتغيير؛ لأن القديم لا يجوز انتقاله وتغيره، وأن يجرى عليه سمات الحدث؛ لأن ما جرى ذلك عليه ولزمته الضعة لم ينقل من سمات الحدث، وما لم يسبق المحدث كان محدثا مصنوعا؛ فبطل بذلك قدم النطفة وغيرها من الأجسام.\rمسألة\rفإن قال قائل: لم زعمتم أن الباري سبحانه لا يشبه المخلوقات؟ قيل [له]: لأنه لو أشبهها لكان حكمه في الحدث حكمها، "], [20, "ولو أشبهها لم يخل من أن يشبهها من كل الجهات أو من بعضها. فإن أشبهها من جميع الجهات كان محدثا مثلها من جميع الجهات، وإن أشبهها من بعضها كان محدثا من حيث أشبهها، ويستحيل أن يكون المحدث لم يزم قديما. وقد قال الله تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ} [الشورى: 11]. وقال تعالى: {لَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} [الإخلاص: 4].\rمسألة\rفإن قال قائل: لم قلتم إن صانع الأشياء واحد؟ قيل له: لأن الاثنين لا يجري تدبيرهما على نظام ولا بد أن يلحقهما العجز أو واحدا منهما؛ لأن أحدهما إذا أراد أن يحيي إنسانا وأراد الآخر أ، يميته لم يخل أن يتم مرادهما جميعا أو لا يتم مرادهما، أو يتم [مراد أحدهما دون الآخر. ويستحيل أن يتم] مرادهما جميعا، لأنه يستحيل أن يكون الجسم حيا ميتا في حال واحدة. وإن لم يتم مرادهما جميعا وجب عجزهما، والعاجز لا يكون إلها ولا قديما. (وإن تم مراد أحدهما دون الآخر وجب عجز من لم يتم مراده منهما والعاجز لا يكون إلها ولا قديما) فدل ما قلناه على أن صانع "], [21, "الأشياء واحد (¬1). وقد قال الله تعالى: {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22] فهذا معنى احتجاجا آنفا.\rمسألة\rفإن قال قائل: ما الدليل على جواز إعادة الخلق؟ قيل له: الدليل على ذلك أن الله سبحانه خلقه أولا لا على مثال سبق، فإذا خلقه أولا لم يعيه أن يخلقه خلقا آخر. وقد قال عز وجل: {وَضَرَبَ لَنَا مَثَلًا وَنَسِيَ خَلْقَهُ قَالَ مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ (78) قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ} [يس: 78، 79] فجعل النشأة الأولى دليلا على جواز النشأة الآخرة لأنها في معناها. ثم قال: {الَّذِي جَعَلَ لَكُمْ مِنَ الشَّجَرِ الْأَخْضَرِ نَارًا فَإِذَا أَنْتُمْ مِنْهُ تُوقِدُونَ} [يس: 80] فجعل ظهور النار على حرها ويبسها من الشجر الأخضر على نداوته \r¬__________\r(¬1))) بقي بعد ذلك احتمال أن يتفقا ولا بد من إبطال هذا الاحتمال أيضا حتى يتم الدليل. ويرى الإمام محمد عبده في رسالته - ص 40 - 41 الطبعة العاشرة لرشيد رضا - أ، هذا الاحتمال باطل إذ لو تعدد واجب الوجود لكان لكل من الواجبين تعين يخالف تعيين الآخر بالضرورة وإلا لم يتحصل معنى التعدد. وكلما اختلفت التعينات اختلفت الصفات الثابتة الذوات المتعينة فيختلف العلم والإرادة مثلا باختلاف الذوات الواجبة فتتخالف أفعالهم بتخالف علومهم وإراداتهم وهو خلاف يستحيل معه الوفاق فيفسد نظام الكون بل يستحيل له نظام. ولذلك كانت الآية: {لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا} [الأنبياء: 22] قطعية الدلالة على الوحدة في رأيه خلافا للسعد وغيره من المتكلمين فإنهم يرونها إقناعية."], [22, "ورطوبته دليلا على جواز خلقه الحياة في الرمة البالية والعظام النخرة، وعلى قدرته على خلق مثله. ثم قال: {أَوَلَيْسَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِقَادِرٍ عَلَى أَنْ يَخْلُقَ} [الفاتحة: 81]. وهذا هو المعول عليه في الحجاج في جواز إعادة الخلق.\rوهذا هو الدليل أيضا على صحة الحجاج والنظر؛ لأن الله تعالى حكم في الشيء بحكم مثله وجعل سبيل النظير ومجراه مجرى نظيره. وقد قال الله تعالى: {اللَّهُ يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ} [يونس: 34]. وقوله تعالى: {وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَهُوَ أَهْوَنُ عَلَيْهِ} [الروم: 27]- يريد وهو هين عليه - فجعل الابتداء كالإعادة. فإن قال قائل: زيدوني وضوحا في صحة النظر. قيل له: قول الله تعالى مخبرا عن إبراهيم عله السلام لما رأى الكوكب: {قَالَ هَذَا رَبِّي فَلَمَّا أَفَلَ قَالَ لَا أُحِبُّ الْآفِلِينَ (76) فَلَمَّا رَأَى الْقَمَرَ بَازِغًا قَالَ هَذَا رَبِّي فَلَمَّا أَفَلَ قَالَ لَئِنْ "], [23, "لَمْ يَهْدِنِي رَبِّي لَأَكُونَنَّ مِنَ الْقَوْمِ الضَّالِّينَ} [الأنعام: 76، 77]. فجمع عليه السلام القمر والكوكب في أنه لا يجوز أن يكون واحد منهما إلها ربا لاجتماعهما في الأفول، وهذا هو النظر والاستدلال الذي ينكره المنكرون وينحرف عنه المنحرفون (¬1).\rمسألة\rفإن قال قائل: لم أنكرتم أن يكون الله تعالى جسما؟ قيل له: أنكرنا ذلك لأنه لا يخلو أن يكون القائل لذلك أراد ما أنكرتم أن يكون طويلا عريضا مجتمعا، أو أن يكون أراد تسميته جسما وإن لم يكن طويلا عريضا مجتمعا عميقا. فإن كان أراد ما أنكرتم أ، يكون طويلا عريضا مجتمعا كما يقال ذلك للأجسام فيما يلينا فهذا لا يجوز؛ لأن المجتمع لا يكون شيئا واحدا؛ لأن أقل قليل الاجتماع لا يكون إلا من شيئين؛ لأن الشيء الواحد لا يكون لنفسه مجامعا؛ وقد بينا آنفا أن الله عز وجل شيء واحد؛ فبطل بذلك أن يكون مجتمعا. \r¬__________\r(¬1))) يعالج المؤلف هذه النقطة على نطاق أوسع في كتيبه المسمى ((رسالة في استحسان الخوض في علم الكلام)) المطبوع بحيدر اباد بالهند سنة 1323 ه كما أشرنا إلى ذلك في المقدمة. والذي أعاد طبعه الأب مكارثي ضمن مجموعة تحت عنوان ((توحيد الأشعري)). المطبعة الكاثوليكية ببيروت سنة 1953 م."], [24, "وإن أراد لم لا تسمونه جسما وإن لم يكن طويلا عريضا مجتمعا؟ فالأسماء ليست إلينا، ولا يجوز أن نسمي الله تعالى باسم لم يسم به نفسه، ولا سماه به رسوله، ولا أجمع المسلمون عليه ولا على معناه.\rمسألة\rفإن قال قائل: لم قلتم إن الله تعالى عالم؟ قيل له: لأن الأفعال المحكمة لا تتسق في الحكمة إلا من عالم. وذلك أنه لا يجوز أن يحوك الديباج النفارير (¬1) ويصنع دقائق الصنعة من لا يحسن ذلك ولا يعلمه. فلما رأينا الإنسان على ما فيه من اتساق الحكمة كالحياة التي ركبها الله فيه والسمع والبصر وكمجاري الطعام والشراب وانقسامهما فيها وما هو عليه من كماله وتمامه، والفلك وما فيه من شمسه وقمره وكواكبه ومجاريها، دل ذلك على أن الذي سنع ما ذكرناه لم يكن يصنعه إلا وهو عالم بكيفيته وكنهه. ولو جاز أن تحدث الصنائع الحكمية لا من عالم لم ندر لعل جميع ما يحدث من حكم الحيوان وتدابيرهم وصنائعهم \r¬__________\r(¬1))) النفارير جمع نفرور وهو العصفور، والجملة في الأصل مكتبة: ((وذلك أنه لا يجوز أن يحوك الديباج بالنقاوير)) وقد تركها كما هي في الأصل بغير تنبيه كما ترك ترجمتها وهي على ذلك لا معنى لها كما أنها تحتاج إلى إصلاح قطعا ولعل ما فعلناء هو المقصود المؤلف. فإن المعنى على ذلك واضح لأن حياكة الديباج يوساطة العصافير مستحيل لانعدام العلم بذلك عندها."], [25, "يحدث منهم وهم غير عالمين؛ فلما استحال ذلك دل على أن الصنائع المحكمة لا تحدث إلا من عالم.\rكذلك لا يجوز أن تحدث الصنائع إلا من قادر حي؛ لأنه لو جاز حدوثها ممن ليس بقادر ولا حي لم ندر لعل سائر ما يظهر من الناس يظهر منهم وهم عجزة موتى؛ فلما استحال ذلك دلت الصنائع على أن الله حي قادر.\rمسألة\rفإن قال: أتقولون إن الله تعالى لم يزل عالما قادرا سميعا بصيرا؟ قيل له: كذلك نقول. فإن قال: فما الدليل على ذلك؟ قيل له: الدليل على ذلك أن الحي إذا لم يكن عالما كان موصوفا بضد العلم "], [26, "من الجهل أو الشك أو الآفات فلو كان [ال] باري تعالى لم يزل حيا غير عالم لكان [لم يزل] موصوفا بضد العلم. ولو كان [لم يزل] موصوفا بضد العلم من الجهل أو الشك أو الآفات لاستحال أن يعلم؛ لأن ضد العلم لو كان قديما لاستحال أن يبطل، وإذا استحال أن يبطل ذلك لم يجز أن يصنع الصنائع الحكمية. فلما صنعها ودلت على أنه عالم صح وثبت أنه لم يزل عالما؛ إذ قد استحال أن يكون لم يزل بضد العلم موصوفا.\rوكذلك لو كان لم يزل حيا غير قادر لوجب أن يكون لم يزل عاجزا موصوفا بضد القدرة. ولو كان عجزة قديما لاستحال أن يقدر وأن تحدث الأفعال منه.\rوكذلك لو كان لم يزل حيا غير سميع ولا بصير لكان لم يزل موصوفا بضد السمع من الصمم والآفات، وبضد البصر من العمى والآفات، ومحال جواز الآفات على الباري، لأنها من سمات الحدث. فدل ما قلناه على أن الله تعالى لم يزل عالما قادرا سميعا بصيرا.\rمسألة\rفإن قال قائل: لم قلتم إن للباري تعالى علما به علم؟ قيل له: لأن الصنائع الحكمية كما لا يقع منا إلا من عالم كذلك لا تحدث منا "], [27, "إلا من ذي علم، فلو لم تدل الصنائع على علم من ظهرت منه منا لم تدل على أن من ظهرت منه منا فهو عالم، فاو دلت على أن الباري تعالى عالم قياسا على دلالتها على (أنا علماء) ولم تدل على أن له علما قياسا على دلالتها على أن لنا علما لجاز لزاعم أ، يزعم أنها تدل على علمنا ولا تدل على أنا علماء. وإذا لم يجز هذا لم يجز ما قاله هذا القائل.\rفإن قال: فما أنكرتم أن لا تدل الأفعال الحكمية على علم العالم منا، كما دلت على أنه عالم؛ لأنه ليس معنى العالم منا أن له علما؛ لأنه قد يعلم العالم منا عالما من لا يعلم أن له علما؟ قيل له: إن جاز لك أن تزعم هذا جاز لغيرك أن يزعم أن الأفعال الحكمية تدل على أن لي علما بها ولا تدل على أني عالم؛ لأنه ليس معنى العالم أن له علما لأنه قد يعلم الإنسان منا أن له لعما من لا يعلمه عالما. وأيضا الناسي (¬1). وأيضا هذه الدعوى عندي فاسدة. وذلك أن معنى \r¬__________\r(¬1))) هي في الأصل ((لناس)) فصححها م إلى ((لناشئ)) وهي بهذا لا معنى لها وأعتقد أنها كما صححتها على معنى أن الناسي له علم وليس عالما وقت نسيانه فيكون ذلك تأييدا لقوله قبل ذلك: ((لأنه قد يعلم الإنسان منا أن له علما من لا يعلمه عالما))."], [28, "العالم عندي أن له علما، ومن لم يعلم لزيد علما، ومن لم يعلم لزيد علما لم يعلمه عالما. فإن قال قائل: فما أنكرتم من أن يدل الفعل الحكمي على أن للإنسان علما هو غيره كما قلتم إنه يدل على علم؟ قيل له: ليس إذا دل الفعل الحكمي على أن للإنسان علما دل على أنه غيره، كما ليس إذا دل على أنه عالم دل على أنه متغاير على وجه من الوجوه. وأيضا فإن معنى الغيرية جواز مفارقة أحد الشيئين للآخر على وجه من الوجوه. فلما دلت الدلالة على قدم الباري تعالى وعلمه استحال أن يكونا غيرين. وأيضا فلو جاز لزاعم أن يزعم أن الفعل الحكمي يدل على أن العالم عالم ثم يعلم علمه بعد ذلك لجاز لزاعم أن يزعم أن الفعل الحكمي يدل على أن العلم علم ثم يعلم أنه لعالم بعد ذلك، وإذا لم يجز هذا وتكافأ القولان وجب أن تكون الدلالة على أن العالم عالم دلالة على العلم.\rفإن قال قائل: من أنه إنما يدل الفعل الحكمي على علم العالم لأنه ممن يجوز أن يموت ويجهل. قيل له: لو جاز هذا لقائله لجاز "], [29, "لزاعم أن يزعم أن الفعل الحكمي يدل أن العالم عالم لأنه ممن يجوز أنه يموت ويجهل.\rومما يبطل قول من قال إن دلالة الفعل الحكمي على علم العالم منا دلالة على أنه غير العالم وأنه محدث أن العالم للعلم ما كان عالما لا للغيرية ولا للحدث، فوجب أن تكون الدلالة على أن العالم عالم دلالة على العلم، ولم يكن العلم علما لأنه غير العالم. ولا لأنه محدث لوجود غير ليس بعلم ومحدث ليس بعلم، فلم يجب أن تكون الدلالة على أن العلم علم دلالة على أنه محدث أو أنه غير العالم. وأيضا فلو جاز لزاعم أن يزعم أن الدلالة على أن العلم علم دلالة على حدثه أو دلالة على أنه غير العالم لجاز لزاعم أن يزعم أن الدلالة على أن العالم [عالم] دلالة على حدثه وأنه متغاير في ذاته.\rوالدليل على أن لله تعالى قدرة وحياة كالدليل على أن لله تعالى علما. وقد قال جل ذكره: ((أنزله بعلمه)) وقال: "], [30, "((وما تحمل من أنثى ولا تضع إلا بعلمه)) فثبت العلم لنفسه. وقال تعالى: {أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ} [فصلت: 15] فثبت القوة لنفسه.\rومما يدل على أن الله تعالى عالم بعلم أنه لا يخلو أن يكون الله تعالى عالما بنفسه أو بعلم يستحيل أن يكون هو نفسه. فإن كان عالما بنفسه كانت نفسه علما؛ لأن قائلا لو قال: إن الله تعالى عالم بمعنى هو غيره لوجب عليه أن يكون ذلك المعنى علما، ويستحيل أن يكون العلم عالما، أو العالم علما، أو يكون الله تعالى بمعنى الصفات. ألا ترى أن الطريق الذي يعلم [به] أ، العلم علم أن العالم به علم؛ لأن قدرة الإنسان التي لا يعلم بها لا يجوز أن تكون علما. فلما استحال أن يكون الباري تعالى علما استحال أن يكون عالما بنفسه، فإذا استحال ذلك صح أنه عالم بعلم يستحيل أن يكون هو نفسه.\rفإن قال قائل: ما أنكرتم أن يكون الباري سبحانه عالما لا بنفسه ولا بمعنى يستحيل أن يكون هو نفسه. قيل له: لو جاز هذا لجاز أن يكون قولنا: ((عالم)) لم يرجع به إلى نفسه ولا إلى معنى ولم يثبت "], [31, "به نفسه ولا معنى يستحيل أ، يكون هو نفسه، وإذا لم يجز هذا بطل ما قالوه.\rوهذا الدليل يدل على إثبات صفات الله تعالى لذاته كلها: من الحياة، والقدرة، والسمع، والبصر، وسائر صفات الذات. "], [33, "(2)\rباب الكلام في القرآن والإرادة\r"]], "pg": [17, 33]}, "477.3": {"x": [[33, "إن قال قائل: لم قلتم إن الله تعالى لم ي زل متكلما وإن كلام الله تعالى غير مخلوق؟ قيل له: قلنا ذلك (¬1) لأن الله تعالى قال: ((إنما قولنا لشيء إذا أردناه أن نقول له كن فيكون)) فلو كان القرآن مخلوقا لكان الله تعالى قائلا له: ((كن)) والقرآن قوله، ويستحيل أن يكون قوله مقولا له (¬2)؛ لأن هذا يوجب قولا ثانيا، والقول في القول الثاني وفي تعلقه بقول ثالث كالقول في القول الأول وتعلقه بقول ثان \r¬__________\r(¬1))) ولكن ما هو القديم في القرآن على رأيه؟ ألفاظه ومعانيه أم المعاني والمدلولات فقط؟ يلزم الأشعري الصمت في الإجابة على هذا الترديد فيما هو معروف حتى اليوم من كتبه وإن كان الشهرستاني ينسب إليه القول بحدوث الألفاظ وقدم المعنى النفسي بينما ينسب إليه بعضهم القول بقدم اللفظ والمعنى معا (أنظر نهاية الأقدام ص 320 وشرح العقائد العضدية ص 188)\r(¬2))) الضمير في قوله: ((له)) يعود في رأيي إلى القول لا إلى الله على معنى أنه يستحيل أن يكون القول مخلوقا بقول آخر وبذلك يتضح الدليل. ويصوره الأشعري في (الإبانة ص 21 القاهرة سنة 1348) هكذا: ((ومما يدل من كتاب الله على أن كلامه غير مخلوق قوله عز وجل: {إِنَّمَا قَوْلُنَا لِشَيْءٍ إِذَا أَرَدْنَاهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} [النحل: 40] فلو كان القرآن مخلوقا لوجب أن يكون مقولا له ((كن)) فيكون. ولو كان الله عز وجل قائلا للقول ((كن)) كان للقول قول، وهذا يوجب أحد أمرين: إما أن يؤول الأمر إلى أن قول الله غير مخلوق، أو يكون كل قول واقعا بقول لا إلى غاية وذلك محال))."], [34, "وهذا يقتضي ما لا نهاية له من الأقوال وهذا فاسد، وإذا فسد ذلك فسد أن يكون القرآن مخلوقا. ولو جاز أن يقول لقوله لجاز أن يريد إرادته، وذلك فاسد عندنا وعندهم، وإذا بطل هذا استحال أن يكون مخلوقا.\rفإن قال قائل: ما أنكرتم أن يكون معنى قوله تعالى ((أن نقول له كن فيكون)) أي نكونه فيكون من غير أن (يقول له في الحقيقة شيئا) قيل له قال الله تعالى: ((إنما قولنا لشيء إذا أردناه أن نقول له كن فيكون)). فلو جاز لقائل أن يقول لم يكن الله تعالى قائلا لشيء في الحقيقة ((كن)) وإنما المعنى أن نكونه فيكون، لجاز لزاعم أن يزعم أن الله تعالى لا يريد شيئا، وإنما معنى ((أردناه)): فعلناه من غير أن تكون إرادة على وجه من الوجوه. فإن قال قائل: أن يكون معنى أن الله تعالى أراد الشيء أنه فعله وهو مريد له في الحقيقة بمعنى أنه فاعل له؟ قيل له: لو جاز هذا لقائله لجاز لزاعم أن يزعم أن الله عز وجل قائل للشيء في الحقيقة ((كن)) ويزعم أن معنى ذلك أنه يكونه فيثبت لله تعالى قولا في الحقيقة هو المقول له، كما زعمتم أن "], [35, "لله تعالى إرادة في الحقيقة هي مراده، ولو جاز لزاعم أن يزعم هذا جاز لآخر أن يقول إن علم الله تعالى بالشيء هو فعله له.\rفإن قال قائل: أليس قد قال الله تعالى ((جدارا يريد أن ينقض)) ولا إرادة للجدار في الحقيقة وإنما قال ((يريد)) توسعا، والمعنى أنه ينقض؟ قيل له: نعم. فإن قال: فما أنكرتم أن يكون معنى ((أن نقول له كن)) أي نكونه فيكون؟ قيل له: الفرق بين ذلك أن الجماد يستحيل مع جماديته أن يكون مريدا والباري تعالى في الحقيقة لا يستحيل عليه أن يريد أو يقول، فلذلك لم يكن قوله: ((أن نقول له كن فيكون)) بمعنى نكونه. وأيضا فلو كان قوله: ((أن نقول له)) ليس معناه إثبات قول له وإنما معناه أن نكونه كما أن قوله ((جدارا يريد أن ينقض)) معناه أن ينقض، لجاز لزاعم أن يزعم أن [معنى] قوله ((أردناه)): فعلناه، وهو في الحقيقة لا يريد فعله. كما أن قوله: ((جدارا يريد أن ينقض)) معناه أنه ينقض، وهذا أولى في حقيقة القياس، وإذا لم يجب هذا لم يجب ما قاله.\rويقال لهم: إذا كانت معنى أن الله تعالى أراد فعل الشيء أنه فعله، ومعنى أراد حركة الشيء أنه حركه، فما أنكرتم أن يكون الجماد في الحقيقة مريدا لحركة نفسه بمعنى أنه متحرك، وأن لا يكون للباري تعالى على الجماد مزية في الإرادة، وأن لا يكون له مزية على من "], [36, "وقع فعله وهو غير مريد له لأنه قد حصل له معنى فاعل كما حصل للباري تعالى معنى فاعل؟\rفإن قال: فما معنى قوله تعالى: {قَالَتَا أَتَيْنَا طَائِعِينَ} [فصلت: 11]؟ قيل له: معنى ذلك أنهما قالتا في الحقيقة: ((أتينا طائعين)).\rومما يدل من القياس على أن الله تعالى لم يزل متكلما أنه لو كان لم يزل غير متكلم - وهو ممن لا يستحيل عليه الكلام - لكان موصوفا بضد الكلام، ولكان ضد الكلام قديما، ولو كان ضد الكلام قديما لاستحال أن يعدم وأن يتكلم الباري؛ لأن القديم لا يجوز عدمه كما لا يجوز حدوثه، فكان يجب أن لا يكون الباري قائلا ولا آمرا ولا ناهيا على وجه من الوجوه، وهذا فاسد عندنا وعندهم، وإذا فسد هذا صح وثبت أن الباري لم يزل متكلما قائلا.\rفإن قال قائل: ولم زعمتم أنه لو كان لم يزل غير متكلم لكان موصوفا بضد الكلام؟ قيل له: لأن الحي إذا لم يكن موصوفا بالكلام كان موصوفا بضده، كما أنه إلا لم ي كن موصوفا بالعلم كان موصوفا بضده؛ وذلك أن الحي فيما بيننا ذلك حكمه ولم تقم دلالة على حي يخلو من الكلام وأضداده في الغائب كما لم تقم دلالة على حي يخلو "], [37, "من العلم وأضداده حتى يكون لا موصوفا بأنه عالم ولا بضد العلم، فقد اجتمع الأمر فيهما: أنه مستحيل فيما بيننا حي غير (عالم ولا موصوف بضد العلم، وأنه مستحيل فيما بيننا حي غير) متكلم ولا موصوف بضد الكلام وأنه لم يقم على ذلك دلالة في الغائب. فلو جاز أحد الأمرين وهو: حي غير متكلم ولا موصوف بضد الكلام، لجاز الأمر الآخر وهو: حي غير عالم ولا موصوف بضد العلم. وأيضا فإنه يستحيل فيما بيننا عالم يوصف بضد العلم مع علمه، ومتكلم يوصف بضد الكلام مع كلامه، فلما اجتمعا في الإحالة وجب أن يكون من جوز متكلما في الغائب يوصف بضد الكلام مع كلامه، كمن جوز عالما في الغائب يوصف بضد العلم مع علمه، فكذلك يجب أيضا لما استحال فيما بيننا حي غير عالم ولا موصوف بضد العلم، وجب أن يستحيل فيما بيننا حي غير متكلم ولا موصوف بضد الكلام [و] أن يستحيل ذلك في الغائب، ووجب أن يكون من جوز أحد الأمرين في الغائب كمن جوز الأمر الآخر.\rوهذا هو الدليل على أن الله تعالى لم يزل مريدا؛ وذلك أن الحي إذا كان غير مريد لشيء أصلا وجب أن يكون موصوفا بضد من أضداد الإرادات كالسهو والكراهة والإيناء (¬1) والآفات، كما وجب \r¬__________\r(¬1))) من آنى إذا آخر ومنه الحديث ((آنيت وآذيت ((أي أخرت المجيء عن وقته وهي في الأصل ((الانما)) (بنقط النون فقط) فاقترح م أن تكون الأبناء، وظاهر أن رسم الكلمة يأبى ذلك وليس من شك في أن الإيناء بمعنى التأخير يعتبر من أضداد الإرادة وقد يشهد لأنها ((الإباء)) قول الشيخ في ص 49: ولو كان ما يكره كونه لكان ما يأبى كونه))."], [38, "أن الحي إذا كان غير عالم بشيء أصلا [كان] موصوفا بضد من أضداد العلوم كالجهل والسهو والغفلة أو الموت وما أشبه ذلك من اللآفات. فلما استحال أن يكون الباري تعالى لم يزل موصوفا بضد الإرادة لأن هذا يوجب أن لا يريد شيئا على وجه من الوجوه؛ وذلك أن ضد الإرادة إذا كان الباري تعالى لم يزل موصوفا به يوجب قدمه ومحال عدم القديم، كما محال حدوث القديم؛ فإذا استحال عدمه وجب أن لا يريد الباري شيئا ويقصد فعله على وجه من الوجوه وذلك فاسد. وإذا فسد هذا صح وثبت أن الباري تعالى لم يزل مريدا.\rفإن قال قائل: لم قلتم إذا كان من لم يزل غير متكلم ولا مريد وجب أن يكون موصوفا ب د الإرادة والكلام إذا كان ممن لا يستحيل عليه الكلام والإرادة، فما أنكرتم من أنه من لم يزل غير فاعل وجب أن يكون موصوفا بضد الفعل وأن يكون تاركا فيما لم يزل؟ قيل له: لا يجب ما قلته؛ وذلك أن للكلام ضدا ليس بكلام، "], [39, "وللإرادة ضدا ليس بإرادة، فوجب لو كان الباري تعالى حيا غير متكلم ولا مريد أن يكون موصوفا بضد الكلام والإرادة وليس للفعل ضد ليس بفعل، فيجب بنفي الفعل عن الفاعل وجود ضده لأن الموجود إذا لم يكن فعلا كان قديما، والقديم لا يضاد المحدثات فلما لم يكن للفعل ضد ليس بفعل لم يجب بنفي الفعل عن الله تعالى في أزله الكلام عن الله تعالى في أزله إثبات ذلك الضد لا محالة.\rفإن قال: فيجب إذا كان القديم غير فاعل فيما لم يزل أن يكون عاجزا أو تاركا. قيل له: فليس العجز مضادا للفعل. وذلك أنه ليس من جنس من أجناس الفعل من حركة وسكون وغيرهما من سائر الأعراض إلا وقد يجوز أن يخلقه الله مع العجز، فعلمنا بذلك أن العجز لا يضاد الفعل؛ لأن الأجسام والجواهر من أفعال الله "], [40, "تعالى؛ فعلمنا أن العجز لا يضاد الفعل؛ لأن عجزي لو ضاد فعلى للحركة لكان تضاد وقوع الحركة من ربي في جسمي. ألا ترى أنه إذا استحال أن أفعل في علما مع الموت استحال أن يفعل ربي في مع الموت علما، فلما لم يكن العجز مضادا للفعل وإنما يضاد القدرة وكان الترك للشيء فعل ضده كان الباري تعالى لم يزل غير فاعل لشيء أصلا، ولم يجب بنفي الفعل عنه في أزله عجز ولا ترك.\rوأيضا فإن الحي إذا كان غير متكلم ولا مريد وجب أن يكون موصوفا بضد الإرادة والكلام، وليس إذا كان غير فاعل لشيء يجب إثبات ضد هو عجز أو ترك إذ كان عجز الإنسان لا يضاد فعله فلم يجب بنفي الفعل عن الله تعالى في أزله إثبات ترك أو عجز، كما وجب في نفي الكلام والإرادة عنه في أزله إثبات أضدادهما.\rفإن قال: فيجب بنفي الحركة عن الله تعالى في أزله أن يكون ساكنا. قيل: لو كان ممن يجوز أن يتحرك لوجب - لعمري - بنفي الحركة عنه أ، يكون ساكنا كما يجب بنفي الكلام والإرادة عنه في أزله إثبات أضدادهما، إذ كان ممن لا يستحيل ذلك عليه. "], [41, "فإن قال: فيجب بنفي التفضل عنه فيما لم يزل أن يكون بخيلا. قيل له: التفضل هو ما للمتفضل أن يتفضل به وله أن لا يتفضل به، والبخل إنما يجب بمنع مستحق استحق على من بخل. والباري تعالى لا يجب عليه فعل شيء.\rفإن قال: فيجب بنفي العدل عنه في أزله أن يكون جائرا أو عاجزا. قيل له: ليس يجب بنفي العدل ضد هو عجز أو جور؛ لأنه ليس من جنس من أجناس العدل إلا ويجوز أن يفعله الله تعالى فينا مع العجز. فلم يجب بنفي العدل إثبات ضد هو عجز، ولم يجب أيضا إثبات الجور؛ لأن الإنسان قد لا يكون عادلا إذا لم يكن منه عدل كسبه ولا فعله ولا يكون جائرا، فليس من نفينا عنه العدل أثبتنا له ضدا هو جور أو عجز؛ إذ كنا قد ننفي ذلك عنا، ولا نثبت ضدا هو عجز أو جور، والحي منا ومن غيرنا إذا لم يكن عالما كان موصوفا بضد العلم. وأيضا فقد لا يكون الإنسان عادلا ولا يكون جائرا بجور من جنس العدل فليس يجب بنفي العدل ضد هو جور كما وجب في الكلام والإرادة؛ لأن الإنسان قد يكون عادلا بالكون في المكان إذا أمره الله تعالى أن يكون فيه، ويكون في وقت آخر جائرا بالكون "], [42, "فيه إذا نهاه الله تعالى عن الكون فيه، فيكون العدل من جنس الجور؛ لأن الكون في المكان من جنس الكون فيه.\rفإن قال: ما أنكرتم إذا لم يكن الباري تعالى محركا في أزله أن يكون مسكنا. قيل له: لا يخلو قولك ... ((إذا لم يكن محركا أن يكون مسكنا)) [أن] تعني إذا كان لم يزل غير محرك لنفسه أن يكون مسكنا لها، أو تنعى إذا لم يكن محركا لجسم كان مسكنا له. فإن عنيت إن لم يحرك نفسه كان مسكنا لها فهذا خطأ؛ لأنه يستحيل أن يحرك نفسه؛ ونحن لم نقل إذا لم يتكلم من يستحيل كلامه كان موصوفا بضد الكلام. وإن عنيت إذا لم يكن محركا فيما لم يزل لجسم كان مسكنا له فليس مع الله تعالى في قدمه أجسام فيجب إذا لم يحركها أن يسكنها، وما لم يكن موجودا يستحيل تحركه، فليس إذا لم يحرك ما يستحيل حركته وجب أن يسكنه.\rمسألة\rفإن قال: القادر منا على الكلام في حال قدرته عليه قد خلا من الكلام وأضداده. فهذا ضرب من الخلاف؛ لأن القادر منا على الكلام في حال قدرته عليه متكلم لا محالة، وسندل على ذلك بعد هذا "], [43, "الموضع من كتابنا. على أنا نقول له: ما أنكرت أن يكون القادر على العلم قد خلا من العلم وأضداده. فإن قال: القادر على العلم قد خلا من العلم وأضداده اللذين يقدر عليهما ولا يخلو من علم آخر أو ضده. قيل له: فقل إن القادر على الكلام وضده يخلو منهما ولا يخلو من كلام آخر أو ضده لا يقدر عليهما.\rودليل آخر على أن الله تعالى لم يل متكلما أن الكلام لا يخلو أن يكون قديما أو حديثا. فإن كان محدثا لم يخل أن يحدثه في نفسه أو قائما بنفسه أو في غيره؛ فيستحيل أن يحدثه في نفسه لأنه ليس بمحل للحوادث، ويستحيل أن يحدثه قائما بنفسه لأنه صفة والصفة لا تقوم بنفسها، ويستحيل أن يحدثه في غيره؛ لأن لو أحدثه في غيره لوجب أن نشق لذلك الجسم الذي فيه الكلام من أخص أوصاف "], [44, "الكلام اللازمة له لنفسه اسما، وللجملة التي المحل منها اسما. فإن كان أخص أوصاف الكلام أنه كلام وجب أن يكون ذلك الجسم متكلما، وإن كان أخص أوصافه أنه أمر وجب أن يكون ذلك الجسم آمرا؛ وكذلك إن كان أخص أوصافه أنه نهى وجب أن يكون ذلك الجسم ناهيا؛ فلما استحال أن يتكلم بكلام الله غيره ويأمر بأمره غيره وينهى بنهيه غيره، استحال أن يحدث كلاما في غيره فيكون به متكلما، وإذا فسدت الوجوه التي لا يخلو الكلام منها لو كان محدثا صح أنه قديم وأن الله تعالى لم يزل به متكلما.\rفإن قال: أفليس قد يحدث الله تعالى في غيره فعلا وتفضلا ونعمة وإحسانا ورزقا فيكون فاعلا متفضلا منعما محسنا رازقا فما أنكرتم أن يحدث في غيره كلاما يكون به متكلما؟ قيل له: لو لزم هذا لزم أن يعلم ويقدر بعلم وقدرة يحدثهما في غيره كما يتفضل وينعم ويحسن فيما يحدثه في غيره تفضلا ونعمة وإحسانا ورزقا، فإن لم يلزم هذا لم يلزم ما قلتموه. وأيضا فإن الله تعالى إذا أحدث في غيره تفضلا ونعمة وفعلا وإحسانا ورزقا كان ذلك الجسم موصوفا بأخص أوصاف "], [45, "الفعل والتفضل والرزق والنعمة والإحسان؛ لأنه إن كان التفضل والنعمة والإحسان والفعل قوة لا بد أن يكون ذلك الجسم قويا. وكذلك إن كان علما أو حياة أو إرادة أو سمعا أو بصرا، فيجب إذا أحدث كلاما في غيره أن يشتق كذلك العين من أخص أوصاف الكلام؛ فلما لم يجز ذلك بطل أن يكون الكلام مقيسا على ما قلتم من أن الله تعالى يحدث كلاما في غيره كما يحدث فعله وتفضله ونعمه وإحسانه في غيره.\rفإن قالوا: أفليس قد يحدث الله تعالى كتابة في غيره ولا يكون الشيء الذي قامت به الكتابة كاتبا؟ قيل لهم: إن أحدث الله تعالى في غيره كتابة ضرورة كان ذلك الغير كاتبا باضطرار. وكذلك إن كانت الكتابة كسبا كان ذلك الغير كاتبا باكتساب. فيجب إذا أحدث الله تعالى كلامه في غيره أن يكون ذلك الغير متكلما بكلام الله.\rوهذا الدليل على قدم الكلام هو الدليل على قدم الإرادة لله تعالى؛ لأنها لو كانت محدثة لكانت لا تخلو من أن يكون يحدثها في نفسه، أو في غيره. أو قائمة بنفسها، فيستحيل أن يحدثها (في نفسه؛ لأنه "], [46, "ليس بمحل للحوادث. ويستحيل أن يحدثها) قائمة بنفسها؛ لأنها صفة والصفة لا تقوم بنفسها، كما لا يجو أن يحدث علما وقدرة قائمين بأنفسهما. ويستحيل أن يحدثها في غير؛ لأن هذا يوجب أن يكون ذلك الغير مريدا بإرادة الله تعالى؛ فلما استحالت هذه الوجوه التي لا تخلو الإرادة منها لو كانت محدثة، صح أنها قديمة، وأن الله لم يزل مريدا بها. "], [47, "(3)\rباب الكلام في الإرادة وأنها تعم سائر المحدثات\r"]], "pg": [33, 47]}, "477.4": {"x": [[47, "فإن قال قائل: لم قلتم إن الله تعالى مريد لكل شيء يجوز أن يراد؟ قيل له: لأن الإرادة إذا كانت من صفات الذات بالدلالة التي ذكرناها وجب أن تكون عامة في كل ما يجوز أن يراد على حقيقته كما إذا كانت من صفات الذات بالدلالة التي ذكرناها وجب أن تكون عامة في كل ما يجوز أن يراد على حقيقته كما إذا كان العلم من صفات الذات وجب عمومه لكل ما يجوز أن يعلم على حقيقته. وأيضا فقد دلت الدلالة على أن الله تعالى خالق كل شيء حادث ولا يجوز أن يخلق ما لا يريده. وقد قال الله تعالى {فَعَّالٌ لِمَا يُرِيدُ} [هود: 107]. وأيضا فإنه لا يجوز أن يكون في سلطان الله تعالى ما لا يريده؛ لأنه لو كان في سلطان الله تعالى ما لا يريده لوجب أحد أمرين: إما إثبات سهو وغفلة، أوو إثبات ضعف وعجز ووهن وتقصير عن بلوغ ما يريده. فلما لم يجز ذلك على الله تعالى استحال أ [ن] يكون في سلطانه ما لا يريده. فإن قال:"], [48, "ولم زعمتم ذلك؟ قيل له: زعمنا ذلك لأن المراد إذا وقع لم يلحق من وقع مراده ضعف ولا تقصير عن بلوغ ما يريده بوقع المراد، فوجب أن يلحقه الضعف والتقصير عن بلوغ ما يريده إذا لم يقع مراده. ألا ترى أن من وقع ما يعلمه لم يلحقه جهل ولا ضد من أضداد العلم بذلك الشيء إذا وقع وهو يعلمه. فدل ذلك على أنه إذا لم يقع وهو لا يعلمه وجب جهله أو وصفه بضد من أضداد العلم. وكذلك إذا كان ما يريده لم يجب سهوه ولا ضعفه ولا وهنه ولا تقصيره عن بلوغ ما يريده. وإذا كان ما لا يريده وجب سهوه أو ضعفه ووهنه وتقصيره عن بلوغ ما يريد.\rوأيضا إذا كان في كون ما لا يريده من أفعاله التي اجتمعنا على أنها أفعاله وجوب السهو والغفلة والوهن والتقصير عن بلوغ ما يريده، فكذلك يلزم في كون ما لا يريده من غيره ما يلزم في كون ما لا يريده مما اتفقنا على أنه من أفعاله. ألا ترى أنه إذا لزم من زعم أنه يكون من أفعال الله ما لا يعلم أن يصفه بالجهل أو بضد من أضداد العلوم لزم مثل ذلك من زعم أنه يكون من غيره ما لا يعلمه "], [49, "وكذلك إذا لزم من زعم أن الله يخبر أنه يكون من فعله ما لا يكون التكذيب لله، لزم من زعم أن الله تعالى يخبر أنه يكون من غيره ما لا يكون التكذيب، لا فرق في ذلك بين ما اتفقنا على أنه فعله وبين ما يكون من غيره. وكذلك إذا لزم في كون ما لا يريده الباري تعالى من فعله ضعف وتقصير عن بلوغ ما يريده، أو سهو وغفلة، لزم ذل في كون ما لا يريده من غيره. وأيضا فقد دلت الدلالة على أن كل المحدثات مخلوقات لله تعالى، فإذا استحال أن يفعل الباري تعالى ما لا يريده استحال أن يقع من غيره ما لا يريده؛ إذ كان ذلك أجمع أفعالا لله تعالى. وأيضا فلو كان في العالم ما لا يريده الله تعالى لكان ما يكره كونه. ولو كان ما يكره كونه لكان ما يأبى كونه، وهذا يوجب أن المعاصي كانت شاء الله أم أبى. وهذه صفة الضعيف المقهور، وتعالى ربنا عن ذلك علوا كبيرا.\rفإن قال قائل: خبرونا عن ملك من ملوك الدنيا لو مر برجل مقعد زمن أعمى فشتمه والملك لا يريد شتمه. أتقولون إن الملك يلحقه في ذلك ضعف ووهن وتقصير عن بلوغ ما يريده إذا أراد "], [50, "أن لا يشتمه فشتمه؟ قيل له: أجل، ولو لم يكن ما أراد الزمن من شتمه وكان ما أراده الملك من مدحه إياه كان ذلك أولى بزوال الضعف والوهن عنه، على أن الملك إذا لم يرد شتم الأعمى المقعد له فقد كره شتمه إياه وأبى ذلك، وقد كان شتمه، شاء ذلك الملك أو أباه وهذه صفة الضعف والوهن.\rوأيضا: فإن من إذا أراد منا أمرا كان وإذا لم يرد كونه لم يكن فهو أولى بصفة الاقتدار ممن يريد كون ما لا يكون وأن لا يكون ما يكون؛ ورب العالمين لا يوصف إلا بالوصف الذي هو أولى بصفة الاقتدار. فإن قال قائل: من إذا أراد أمرا كان وإذا لم يرده لم يكن، إنما يكون اقتداره بمن يتبعه ويعينه ويكون ضعفه لقلة أنصاره وأتباعه، ورب العالمين لا يتكثر بأحد. يقال لهم: فما أنكرتم - إن كان هذا على ما تدعون - أن يكون من أراد من فعله كون ما لا يكون "], [51, "وأن لا يكون [ما يكون] فهو أولى بصفة الاقتدار ممن يريد كون ما يكون وأن لا يكون ما لا يكون [لأنه] إنما يصح وصفه بالاقتدار؛ لأنه ممن يتكثر بفعله، ويجب اقتداره بمن ينصرد وضعفه بمن يقعد عنه. ويقال لهم لم زعمتم أن من أراد منا كون ما يكون إنما يصح وصفه بالاقتدار لأنه ممن يقوى بكثرة من يتبعه ويضعف بكثرة من يقعد عنه؟ فإن قالوا: لأن هذا فيما بيننا هكذا قيل [لهم]: وكذلك إنما يدل الفعل الحكمي على أن من ظهر منه عالم قادر لأنه ممن يعلم بعلم ويقدر بقدرة؛ لأنا كذلك وجدنا فيما بيننا من دلت الأفعال الحكمية على أنه عالم قادر، فما أنكرتم من أنه واجب على اعتلالكم أن لا تدل (¬1) الأفعال الحكمية على أن الباري تعالى قادر عالم. وكذلك يعارضون بأن الأفعال الحكمية تدل على أن من هرت منه عالم قادر؛ لأنه ممن له علم وقدرة من أجل أن ذلك فيما بيننا كذلك. \r¬__________\r(¬1))) وضع م حرف النفي بين قوسين وقال أن ابقاءه قد يعطي معنى مخالفا لما أراد المؤلف. وهذا غير صحيح فإن المؤلف يريد أن يقول للمعتزلة إذا احتكمنا للمشاهد فيما بيننا أمكن لنا بناء على هذا أن ننكر دلالة الفعل الحكمي على أن الله عالم قادر لأنكم تنكرون دلالة الفعل الحكمي على أن الله عالم بعلم مع أن المشاهد أن الفعل الحكمي إذا لم يدل على علم العالم لا يدل على كونه عالما. فحيث قد نفيتم الدلالة على العلم وجب نزولا على حكم ((المشاهد)) أن تنفوا الدلالة على أن الله عالم."], [52, "فإن قال قائل: ما أنكرتم أن لا يلحق الباري الضعف والوهن والتقصير عن بلوغ ما يريده لأنه يقدر أن يلجئ عباده إلى ما أراد كونه منهم. قيل له: إن الباري تعالى إنما أراد كون الإيمان منهم على أصلك، بأن يقع ذلك منهم طوعا يستحقون عليه الثواب، وإذا ألجأهم إليه لم يكونوا عندك طائعين، ولا للثواب مستحقين (فكما بحب بكون ما لا يريده) الضعف والوهن والتقصير عن بلوغ ما يريده لو لم يوصف بالقدرة على أن يلجئهم إلى ذلك، كذلك يجب له الضعف والوهن والتقصير عن بلوغ ما يريده إذا أراد كونه على وجه لا يوصف بالقدرة على وقوعه على ذلك الوجه. وأيضا فإنه يلزم القدرية: إذا كان من قدر أن يؤمن قدر أن يكفر، أن لا يكون الباري تعالى موصوفا بالقدرة على الأمر الذي لو فعله لأصبحوا مؤمنين لا محالة؛ لأ (نهم) يقدرون عندهم على أن يكفروا عند نزول الآيات الملجئات كما يقدرون أن يؤمنوا قبل ذلك، ومن قدر على الكفر عند نزول الآية لم يؤمن وقوعه منه. وأيضا فلو كان يقع من الإنسان ما لا يريده الباري سبحانه ولا يلحق الباري بذلك وهن ولا ضعف لأنه قادر أن يلجئهم إليه لجاز أن يقع من الباري "], [53, "سبحانه من أفعاله ما لا يريده ولا يلحقه ضعف وتقصير عن بلوغ ما يريده؛ لأنه قادر على إيقاعه وتكوينه. فإن لم يجب هذا ولزم بكون ما لا يريده من فعله الضعف والوهن، لزم ذلك في فعل عباده.\rفإن قال قائل: ما أنكرتم أن يكون كون ما لا يريده الإنسان من فعله يوجب وقوع ذلك عن (سهو أو عن ضعف ووهن) وليس يلزم ذلك في كون ما لا يريده من فعل غيره فوجب مثل ذلك في القديم أيضا. قيل له: ليس الأمر كما ظننت، بل القصة فيما يكون من الإنسان ومن غيره واحدة؛ وذلك أن الإنسان إذا كان من فعله ما لا ريده فإما أن يكون ذلك عن سهو أو عن ضعف ووهن أو (¬1) تقصير عن بلوغ ما يريده. وكذلك القول فيما يكون من غيره؛ لأنه إن لم يكن ذلك عن سهو فواجب أن يكون عن ضعف وتقصير عن بلوغ ما يريده وذلك أن العلة التي لها لزم الإنسان إذا كان عالما بما وقع منه وهو غير مريد له الضعف والتقصير عن بلوغ ما يريده أن مراده لم يقع وأنه لم يرده؛ لأنه لو كان ما يريده لم يلحقه ضعف ولا وهن \r¬__________\r(¬1))) كذا في ب، ل، م ولعل الأولى أن نقول: (وتقصير)) أو نقول إن ((أو)) هنا بمعنى الواو لأن اللازم أحد أمرين فقط في رأي المؤلف وهما إما الغفلة أو الضعف كما يبدو ذلك واضحا في كلامه."], [54, "فإذا لم يقع فإنما لحقه الوهن والتقصير عن بلوغ ما يريده من أجل أنه وقع منه وهو عالم به غير مريد له. وإذا كانت العلة ما ذكرنا وجب أيضا مثل ذلك فيما يقع من غيره وهو لا يريده؛ لأنه إذا كانت العلة التي لها وجب أن يوصف الإنسان بضد العلم في وقوع ما يقع منه أنه وقع منه وهو لا يعلمه، فكذلك قصة ما يقع من غيره وهو لا يعلمه؛ إذ كانت العلة في ذلك واحدة. وكذلك القول في الإرادة. (وأيضا فإنه) إذا كان من غيره ما لا يريده فقد كرهه وإذا كره كونه فقد أباه وهذا يوجب أن الشيء كان شاء أم أبى وهذه صفة الضعف والوهن.\rفإن قالوا: ما أنكرتم من أن الذي يجب في كون ما لا يريده الباري تعالى من عباده أن يكون كارها لذلك فقط ولا يجب في ذلك ضعف ولا وهن؟ قيل لهم: بل وقوع ذلك منه وهو كاره له يوجب الضعف والوهن لا محالة. ولأنه إذا كان ما كره كونه، كان ما أبى كونه، وإذا كان ما أبى كونه فقد كان الشيء، شاءه أم أباه. وهذا يوجب "], [55, "أن الشيء كان، شاء الله تعالى ذلك أم أباهن وهذه صفة الضعف. وأيضا فإن المعتزلة رجلان: أحدهما يقول إن إرادة الله تعالى في أفعال عباده، الأمر بها. والآخر يقول إرادته في أفعال عباده خلف غير الأمر بها. فمن ذهب إلى أنها الأمر لزمه إذا لم يكن الباري آمرا بأفعال الأطفال والمجانين أن يكون كارها لها؛ إذ كان يجب بنفي الإرادة لأفعال العباد الكراهة لها والله لا يكره إلا معصية، كما لا ينهى إلا عن معصية. وإذا لم يكن هذا عندهم هكذا أبطل ما قالوه. وأيضا فإذا كان يلزم فيما جاز الأمر به إذا لم يأمر به أن يكون له كارها لزم من كان في عصر الرسول صلى الله عليه وسلم وجاز عنده أن ينزل النهي عن المباح الذي ليس بطاعة أن يكون إذا لم يرد من الله تعالى الأمر به قد كره، وهذا يوجب أن كل مباح معصية.\rومن ذهب إلى القول الثاني - وهو قول الجبائي - إن إرادة الله تعالى لأفعال عباده هي غير الأمر بها يقال له: إذا كان يجب "], [56, "بنفي الإرادة لأفعال عباده الكراهة فحدثنا: هل أراد الله كون الأفعال التي ليست بمعاص ولا طاعات؟ فإن قال: نعم. قيل له: يلزمك أن تكون طاعة؛ لأن الطاعة عندك إنما كان طاعة للمطاع (لأنه أرادها) فإن قال: لم يردها. قيل له: فيلزمك أنه كاره لكونها، وهذا يوجب أن تكون معصية؛ لأن ما كرهه الله سبحانه فهو معصية، كما أن ما نهى عنه فهو معصية عندكم. ويقال لهم: إذا كان نفي الإرادة يوجب إثبات كراهة فيلزمكم إذا كان (الله تعالى لم يزل) غير مريد لشيء بتة أن يكون لم يزل كارها، إذ كان نفي الإرادة يوجب إثبات كراهة.\rمسألة\rويقال للمعتزلة: لم زعمتم أنه لا يريد السفه إلا سفيه؟ فإن قالوا: لأن مريد السفه منا سفيه. يقال لهم: فكذلك من أراد منا ما يعلم أنه لا يكون، أو يغلب عنده أنه لا يكون، فهو متمن، فاقضوا بذلك على الله تعالى إذ زعمتم أنه أراد أن يكون ما علم أنه لا يكون. ويقال لهم: وكذلك أيضا من خلى بين "], [57, "عبيده وإمائه يزنى بعضهم ببعض وهو يراهم وهو لا يعجز عن التفريق بينهم مع كراهته الزنا على أصولكم، وقد نهاهم قبل ذلك عن الزنا فهو سفيه، فاقضوا بذلك على الله تعالى وإلا كنتم مناقضين. فإن قالوا: لو جاز أن يريد السفه من ليس بسفيه لجاز أن يقول الكذب من ليس بكاذب. يقال لهم: ما الفرق بينكم وبين من قال ولو جاز أن يريد ما علم أنه لا يكون من ليس بمتمن ويخلى بين عبيده وإمائه يزنى بعضهم ببعض مع كراهته الزنا عندكم وقدرته على المنع والحيلولة من ليس بسفيه لجاز أن يقول الكذب من ليس بكاذب، وهذا ما لا يجدون فيه فرقا. ويقال لهم: كما أن مريد السفه منا سفيه، فكذلك مريد الطاعة منا مطيع، فاقضوا بذلك على الغائب.\rومما يبين أن الله تعالى مريد لكل شيء يجوز أن يراد، قول الله تعالى: {وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ} [الإنسان: 30] فأخبر أنا لا نشاء إلا ما شاء أن نشاءه. وقال تعالى: {وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَنْ فِي الْأَرْضِ "], [58, "كُلُّهُمْ جَمِيعًا} [يونس: 99] وقال تعالى: {وَلَوْ شِئْنَا لَآتَيْنَا كُلَّ نَفْسٍ هُدَاهَا} [السجدة: 13] وقال تعالى: {وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ} [الأنعام: 112]. وقال: {وَلَوْ شَاءَ اللَّهُ مَا اقْتَتَلُوا وَلَكِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ} [البقرة: 253] فأخبر أنه لو لم يرد القتال لم يكن وأن ما أراد من ذلك فقد فعله. فإن قالوا: معنى هذا لو شاء الله ما اقتتلوا: أي لو شاء أن يمنعهم من القتال لم يكن، يقال لهم: ولم لا حملتم (¬1) الآية على ظاهرها وقلتم على أي وجه شاء أن لا يكون القتال لم يكن. وكذلك المطالبة عليهم في قول الله تعالى: {وَلَوْ شَاءَ رَبُّكَ لَآمَنَ مَنْ فِي الْأَرْضِ كُلُّهُمْ جَمِيعًا} [يونس: 99]. فإن قالوا: لو شاء الله أن يلجئهم إلى الإيمان لكانوا مؤمنين، قيل لهم: أو ليسوا مع الإلجاء قادرين على أن يكفروا كما قادرون على أن يؤمنوا؟ فكيف يجب بالإلجاء كون الإيمان منهم وهم قادرون أن لا يكون منهم إيمان مع الإلجاء كما هم قادرون على الإيمان مع عدم الإلجاء؟.\rفإن قالوا: ليس في كون ما لا يريده إيجاب ضعف، كما ليس \r¬__________\r(¬1))) هذا تعبير المصنف يكرره في أكثر من موضع ولا شك في فساده عربية والأصح: ولم لم تحملوا."], [59, "في كون ما لم يأمر به إيجاب ضعف. قيل لهم: قد كانت أفعاله عندكم ولم يأمر بها ولم يلحقه ضعف، ولو كانت وهو لا يريدها لحقه الضعف، فكذلك كون ما لم يأمر به من غيره لا يوجب له ضعفا، وفي كون ما لم يرده من غيره [ما] يدل على الضعف. وأيضا فإن ما لم يأمر به ونهى عنه أراد (¬1) وقوعه، فلذلك لم يلحقه الضعف. \r¬__________\r(¬1))) ب، ل: وأراد وقد أبقاها م كما هي والصواب حذف الواو وإلا فأين خبر ((إن))."], [61, "(4)\rباب الكلام في الرؤية\r"]], "pg": [47, 61]}, "477.5": {"x": [[61, "إن قال قائل: لم قلتم إن رؤية الله تعالى بالأبصار جائزة من باب القياس؟ قيل له: قلنا ذلك لأن ما لا يجوز أن يوصف به الباري تعالى ويستحيل عليه فإنما لا يجوز لأن في تجويزه إثبات حدثه، أو إثبات حدث معنى فيه، أو تشبيهه، أو تجنيسه، أو قلبه عن حقيقته، أو تجويره، أو تظليمه، أو تكذيبه.\rوليس في جواز الرؤية إثبات حدث؛ لأن المرئي لم يكن مرئيا لأنه محدث، ولو كان مرئيا لذلك للزمهم أ، يرى كل محدث، وذلك باطل عندهم. على أن المرئي لو كان مرئيا لحدوثه لكان الرائي محدثا للمرئي، إذ كان مرئيا لحدوثه. وليس في الرؤية إثبات حدوث معنى في المرئي لأن الألوان مرئيات ولا يجوز حدوث معنى فيها [وإلا] لكان ذلك المعنى هو الرؤية، وهذا يوجب أنا إذا رأينا الميت فقد حدثت فيه الرؤية وجامعت الرؤية الموت، وإذا رأينا عين الأعمى حدثت في "], [62, "عينه رؤية فكانت الرؤية مجامعة للعمى؛ فلما لم يجز ذلك بطل ما قالوه. وليس في إثبات الرؤية لله تعالى تشبيه الباري تعالى، ولا تجنيسه ولا قلبه عن حقيقته؛ لأنا نرى السواد والبياض فلا يتجانسان ولا يشتبهان بوقوع الرؤية عليهما، ولا ينقلب السواد عن حقيقته إلى البياض بوقوع الرؤية عليه، ولا البياض إلى السواد. وليس في الرؤية تجويره، ولا تظليمه، ولا تكذيبه، لأنا نرى الجائر والظالم والكاذب، ونرى من ليس بجائر ولا ظالم ولا كاذب؛ فلما لم يكن في إثبات الرؤية شيء مما لا يجوز على الباري لم تكن الرؤية مستحيلة، وإذا لم تكن مستحيلة كانت جائزة على الله ..\rفإن عارضونا بأن اللمس والذوق والشم ليس فيه إثبات الحدث ولا حدوث معنى في الباري تعالى. قيل لهم: قد قال بعض أصحابنا إن اللمس ضرب من ضروب المماسات، وكذلك الذوق وهو اتصال اللسان واللهوات بالجسم الذي له الطعم، وإن الشم هو اتصال الخيشوم بالمشموم الذي يكون عنده الإدراك له، وإن المتماسين إنما يتماسان بحدوث مماسين مماسين فيهما، وإن في إثبات ذلك إثبات حدوث معنى في "], [63, "الباري. ومن أصحابنا من يقول: لا يخلو القائل أن يكون أراد بذكره الذوق واللمس [والشم] أن يحدث الله تعالى له إدراكا في هذه الجوارح من غير أن يحدث فيه معنى، أو يكون أراد حدوث معنى فيه. فإن كان أراد حدوث معنى فيه فذلك ما لا يجوز، وإن كان أراد حدوث إدراك فينا فذلك جائز، والأمر في التسمية إلى الله تعالى إن أمرنا أن نسميه لمسا وذوقا وشما (سميناه)، وإن معننا امتنعنا، وأما السمع فلم يختلف أصحابنا فيه وجوزوه جميعا، وقالوا إنه جائز أن يسمعنا الباري تعالى نفسه متكلما.\rوالدليل على أن الله تعالى يرى بالإبصار قوله تعالى: {وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ (22) إِلَى رَبِّهَا نَاظِرَةٌ} [القيامة: 22، 23] ولا يجوز أن يكون معنى قوله: {إِلَى رَبِّهَا نَاظِرَةٌ} [القيامة: 23] معتبرة كقوله تعالى {أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ} [الغاشية: 17] لأن الآخرة ليست بدار اعتبار. ولا يجوز أن يعنى متعطفة راحمة كما قال: "], [64, "{وَلَا يَنْظُرُ إِلَيْهِمْ} [آل عمران: 77] أي لا يرحمهم ولا يتعطف عليهم؛ لأن الباري لا يجوز أن يتعطف عليه. ولا يجوز أن يعني منتظرة؛ لأن النظر إذا قرن بذكر الوجوه لم يكن معناه نظر القلب الذي هو انتظار، كما إذا قرن النظر بذكر القلب لم يكن معناه نظر العين؛ لأن القائل إذا قال انظر بقلبك في هذا الأمر كان معناه نظر القلب، وكذلك إذا قرن النظر بالوجه لم يكن معناه إلا نظر الوجه، والنظر بالوجه هو نظر الرؤية التي تكون بالعين التي في الوجه؛ فصح أن معنى قوله تعالى: ((إلى ربها ناظرة)): رائية؛ إذ لم يجز أن يعني شيئا من وجوه النظر [الأخرى]. وإذا كان النظر لا يخلو من وجوه أربع وفسد منها ثلاثة أوجه، صح الوجه الرابع وهو نر رؤية العين التي في الوجه.\rفإن قال قائل: أليس قد قال الله تعالى: {وَوُجُوهٌ يَوْمَئِذٍ بَاسِرَةٌ (24) تَظُنُّ أَنْ يُفْعَلَ بِهَا فَاقِرَةٌ} [القيامة: 24، 25] والن لا يكون بالوجه فكذلك قوله تعالى: {وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ (22) إِلَى رَبِّهَا نَاظِرَةٌ} [القيامة: 22، 23] أراد نظر القلب؟ "], [65, "قيل له: لأن الظن لا يكون بالوجه ولا يكون إلا بالقلب، فلما قرن الظن بذكر الوجه كان معناه ظن القلب إذ لم يكن الظن إلا به، فلو كان النظر لا يكون إلا بالقلب لوجب إذا ذكره مع ذكر الوجه أن يرجع به إلى القلب، فلما كان النظر قد يكون بالوجه وبغيره وجب إذا قرنه بذكر الوجه أن يريد به نظر الوجه، كما أنه إذا قرنه بذكر القلب وجب أن يريد به نظر القلب.\rمسألة\rفإن قالوا: فما معنى قوله تعالى: {لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ} [الأنعام: 103]؟ قيل لهم: في الدنيا دون الآخرة؛ لأن القرآن لا يتناقض، فلما قال في آية أخرى: إنه (لا تدركه) الأبصار علمنا أن الوقت الذي قال إنه لا تدركه الأبصار فيه غير الوقت الذي أخبرنا أنها تنظر إليه فيه.\r[فإن] قال قائل: ما أنكرتم أن يكون قوله تعالى: {إِلَى رَبِّهَا نَاظِرَةٌ} [القيامة: 23]: أي إلى ثواب ربها ناظرة؟ قيل له: ثواب الله تعالى غيره، ولا يجوز أن يعدل بالكلام عن الحقيقة إلى المجاز بغير حجة ولا دلالة. ألا ترى أن الله تعالى لما قالك صلوا لي واعبدوني، لم يجز أن يقول قائل "], [66, "عني غيره. ولو جاز [هذا لجاز (¬1)] لزاعم أن يزعم أن قوله: {لَا تُدْرِكُهُ} [الأنعام: 103] أراد به أنه لا تدرك غيره الأبصار. فإن قال: فإذا كان قوله {لَا تُدْرِكُهُ الْأَبْصَارُ} [الأنعام: 103] [يعني] في وقت دون وقت فما أنكرت أن يكون قوله: {لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ} [البقرة: 255] [يعني] في وقت دون وقت؟ قيل له: الفرق بينهما أنه قال لنا في آية إنه لا تدركه الأبصار، وقال في آية أخرى إن الوجوه تنظر إليه، فاستعملنا الآيتين وقلنا إن المعنى في ذلك أنها تنظر إليه في وقت ولا تدركه في وقت، ولم يقل لنا في آية إن السنة والنوم تأخذانه وفي آية أخرى لا تأخذانه، فيستعمل في وقتين. وأيضا فإن النوم آفة تقوم بالنائم تزيل عنه العلم، وليست الرؤية آفة تحل في المرئي فيجب منع الرؤية بمثل ما به وجب منع النوم. \r¬__________\r(¬1))) ما بين قوسين ليس في الأصل وزيادته ضرورية لتمام التعبير وكمال المعنى وقد اقترح م إصلاح التعبير على نحو آخر أشرنا إليه في المقدمة."], [67, "مسألة\rفإن قالوا: لو جاز أن يرى القديم سبحانه وليس كالمرئيات لجاز أن يلمس ويذاق ويشم وليس كالمذوقات ولا كالملموسات ولا كالمشمومات. قيل لهم: ما الفرق بينكم وبين من قال: ولو جاز أن يكون القديم رائيا عالما قاجرا حيا لا كالرائين العلماء القادرين الأحياء لجاز أ، يكون لامسا ذائقا شاما لا كاللامسين الذائقين الشامين؟ فإن [لم] يجب هذا فما أنكرتم من أن لا يجب ما قلتموه.\rمسألة\rفإن قال قائل: فهل شاهدتم مرئيا إلا جوهرا أو عرضا محدودا أو حالا في محدود؟ قيل له: لا، ولم يكن المرئي مرئيا لأنه محدود ولا لأنه حال في محدود، ولا لأنه جوهر، ولا لأنه عرض؛ فلما لم يكن ذلك كذلك لم يجب القضاء بذلك على الغائب، كما لم يجب إذا لم نجد فاعلا إلا جسما ولا شيئا إلا جوهرا أو عرضا ولا عالما قادرا "], [68, "حيا إلا بعلم وحياة وقدرة محدثة أن يقضى بذلك على الغائب؛ إذ لم يكن الفاعل فاعلا لأنه [جسم] ولا الشيء شيئا لأنه جوهر أو عرض. "], [69, "(5)\rباب الكلام في القدر\r"]], "pg": [61, 69]}, "477.6": {"x": [[69, "إن قال قائل: لم زعمتم أن أكساب العباد مخلوقة لله تعالى؟ قيل له: قلنا ذلك لأن الله تعالى قال: {وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] وقال: {جَزَاءً بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 17]. فلما كان الجزاء واقعا على أعمالهم كان الخالق لأعمالهم. فإن قال: أفليس الله تعالى قال: {أَتَعْبُدُونَ مَا تَنْحِتُونَ} [الصافات: 95] وعنى الأصنام التي نحتوها، فما أنكرتم أن يكون قوله: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] أراد الأصنام التي عملوها؟ قيل له: خطأ ما ظننته؛ لأن الأصنام منحوتة لهم في الحقيقة فرجع الله تعالى بقوله: {أَتَعْبُدُونَ مَا تَنْحِتُونَ} [الصافات: 95] إليها، وليست الخشب معمولة لهم في الحقيقة فيرجع بقوله: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] إليها.\rفإن قال قائل: أليس قد قال الله تعالى: {تَلْقَفُ "], [70, "مَا يَأْفِكُونَ} [الأعراف: 117] ولم يرد إفكهم، فما أنكرت أن لا يرجع بقوله: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] إلى أعمالهم؟ قيل له: الذي يأفكون هو الأمثلة التي خيلوا إلى الناس أنها حيات تسعى، وإفكهم تخييلهم، فأراد بقوله: {يَأْفِكُونَ} [الأعراف: 117] أ] يخيلون إلى الناس أنها حيات تسعى، وإفكهم هو إيهامهم الشيء على خلاف ما هو بسبيله، فالأمثلة هي التي يأفكون ويخيلون إلى الناس أنها تسعى في الحقيقة، وهي التي تلقفها العصا. وليس يجوز أن يعملوا الخشب في الحقيقة فلم يجز أن يكون الله تعالى أراد بقوله: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] [الرجوع] إليها ووجب أن يرجع إلى الأعمال كما رجع بقوله: {جَزَاءً بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 17] إلى الأعمال، فلو جاز لزاعم أن يزعم أن قول الله تعالى: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] أراد [به] غير أعمالهم كما أراد بقوله {مَا يَأْفِكُونَ} [الأعراف: 117] غير إفكهم، لساغ أن يزعم أن قول الله تعالى: {جَزَاءً بِمَا كَانُوا يَعْمَلُونَ} [السجدة: 17] إنما أراد به غير أعمالهم كما أراد بقوله: {خَلَقَكُمْ وَمَا تَعْمَلُونَ} [الصافات: 96] غير أعمالهم، كما أن قوله: {مَا يَأْفِكُونَ} [الأعراف: 117] إنما أراد به غير إفكهم؛ فلما لم يجز هذا لم يجز ما قاله هذا. "], [71, "الدليل من القياس على خلق أعمال الناس: أنا وجدنا الكفر قبيحا فاسدا باطلا متناقضا خلافا لمن خالف، ووجدنا الإيمان حسنا متعبا مؤلما، ووجدنا الكافر يقصد ويجهل نفسه إلى أن يكون الكفر حسنا حقا فيكون بخلاف قصده، ووجدنا الإيمان لو شاء المؤمن أن لا يكون متعبا مؤلما ولا مرمضا لم يكن ذلك كائنا على حسب مشيئته وإرادته. وقد علمنا أن الفعل لا يحدث على حقيقته إلا من محدث أحدث أحدثه عليها؛ لأنه لو جاز أ، يحدث على حقيقته لا منم محدث أحدثه على ما هو عليها لجاز أ، يحدث الشيء فعلا لا من محدث أحدثه فعلا؛ فلما لم يجز ذلك صح أنه لم يحدث على حقيقته إلا من محدث أحدثه على ما هو عليه وهو قاصد إلى ذلك؛ لأنه لو جاز حدوث فعل على الحقيقة لا من قاصد لم يؤمن أن تكون الأفعال كلها كذلك كما أنه لو جاز حدوث فعل لا من فاعل لم يؤمن أن تكون الأفعال كلها كذلك؛ وإذا كان هذا هكذا فقد وجب أن يكون للكفر محدث أحدثه كفرا باطلا قبيحا وهو قاصد إلى ذلك، ولن يجوز أن يكون المحدث له هو الكافر الذي يريد أن ي كون الكفر حسنا صوابا "], [72, "حقا فيكون على خلاف ذلك. وكذلك للإيمان محدث أحدثه على حقيقته متعبا مؤلما مرمضا غير المؤمن الذي لو جهد أن يقع الإيمان خلاف ما وقع من إيلامه وإتعابه وإرماضه لم يكن إلى ذلك سبيل، وإذا لم يجز أن يكون المحدث للكفر على حقيقته الكافر، ولا المحدث للإيمان على حقيقته المؤمن، فقد وجب أن يكون محدث ذلك هو الله تعالى رب العالمين القاصد إلى ذلك؛ لأنه لا يجوز أن يكون أحدث ذلك جسم من الأجسام؛ لأن الأجسام لا يجوز أن تفعل في غيرها شيئا.\rفإن قال قائل: فلم لا دل وقوع الفعل الذي هو كسب على أنه لا فاعل له إلا الله، كما دل على أنه لا خالق [له] إلا الله تعالى؟ قيل له: كذلك نقول. فإن قال: فلم لا دل على أنه لا قادر عليه إلا الله عز وجل؟ قيل له: لا فاعل له على حقيقته إلا الله تعالى، ولا قادر عليه أن يكون على ما هو عليه من حقيقته أن يخترعه إلا الله تعالى. فإن قال: فلم لا دل كونه كسبا على حقيقته على أنه "], [73, "لا مكتسب له الحقيقة إلا الله؟ قيل له: الأفعال لا بد لها من فاعل على حقيقتها؛ لأن الفعل لا يستغني عن فاعل، فإذا لم يكن فاعلمه على حقيقته الجسم، وب أن يكون الله تعالى هو الفاعل له على حقيقته وليس لا بد للفعل من مكتسب يكتسبه على حقيقته، كما لا بد من فاعل يفعله على حقيقته، فيجب إذا كان الفعل كسبا كان الله تعالى [هو] المكتسب له على حقيقته. ألا ترى أن حركة الاضطرار تدل على أن الله تعالى هو الفاعل لها على حقيقتها ولا تدل على أن المتحرك بها في الحقيقة، ولا يجب أن يكون المتحرك المضطر إليها فاعلا لها على حقيقتها؛ إذ كان متحركا بها على الحقيقة، إذ كان معنى المتحرك أن الحركة حلته ولم يكن [ذلك] جائزا على ربنا تعالى، وكذلك إذا كان الكسب دالا على فاعل فعله على حقيقته لم يجب أن يدل على أ، الفاعل له على حقيقته هو المكتسب له ولا على أن المكتسب له على الحقيقة هو الفاعل له على الحقيقة؛ إذ كان المكتسب مكتسبا للشيء لأنه وقع بقدرة له عليه محدثة ولم يجز أن يكون "], [74, "رب العالمين قادرا على الشيء بقدرة محدثة فلم يجز أن يكون مكتسبا للكسب وإن كان فاعلا له في الحقيقة.\rفإن قال: فهل اكتسب الإنسان الشيء على حققته كفرا باطلا وإيمانا حسنا؟ قيل له: هذا خطأ، وإنما معنى ((اكتسب الكفر)) أنه كفر بقوة محدثة، وكذلك قولنا ((اكتسب الإيمان)) (معناه أنه آمن) بقوة محدثة من غير أن يكون اكتسب الشيء على حقيقته بل الذي فعله على حقيقته هو رب العالمين. والقول في الكذب وأن له فاعلا [يفعله على] حقيقته وكاذبا به غير من فعله على حقيقته، كالقول في فاعل الحركة على الحقيقة وأن المتحرك بها على الحقيقة غير من فعلها على حقيقتها. وقد بينا ذلك آنفا.\rودليل آخر من القياس على خلق أفعال الناس: أن الدليل على خلق الله تعالى حركة الاضطرار قائم في خلق حركة الاكتساب؛ وذلك أن حركة الاضطرار إن كان الذي يدل على أن الله خلقها حدوثها فكذلك القصة في حركة الاكتساب، وإن كان الذي يدل على "], [75, "خلقها حاجتها إلى مكان وزمان فكذلك قصة حركة الاكتساب. فلما كان كل دليل يستدل به على أن حركة الاضطرار مخلوقة لله تعالى يجب به القضاء على أن حركة الاكتساب مخلوقة لله تعالى، وجب خلق حركة الاكتساب بمثل ما وجب [به] خلق حركة الاضطرار.\rفإن قال قائل: فيجب إذا كانت إحدى الحركتين ضرورة أن تكون الأخرى كذلك، وإذا كان إحداهما كسبا أن تكون الأخرى كذلك. قيل له: لا يجب ذلك لافتراقهما في معنى الضرورة والاكتساب؛ لأن الضرورة ما حمل عليه الشيء وأكره وجبر عليه ولو جهد في التخلص منه وأراد الخروج عنه واستفرغ في ذلك مجهوده لم يجد منه انفكاكا ولا إلى الخروج عنه سبيلا. فإذا كانت إحدى الحركتين بهذا الوصف الذي هو وصف الضرورة، وهي حركة المرتعش من الفالج والمرتعد من الحمي كانت اضطرارا، وإذا كانت الحركة الأخرى بخلاف هذا الوصف لم تكن اضطرارا؛ لأن الإنسان في ذهابه ومجيئه وإقباله وإدباره، بخلاف المرتعش من الفالج والمرتعد من الحمي، يعلم الإنسان التفرقة بين الحالين من "], [76, "نفسه وغيره علم اضطرار لا يجوز معه الشك. فقد وجب إذا كان العجز في إحدى الحالتين أن القدرة التي هي ضده حادثة في الحال الأخرى؛ لأن العجز لو كان في الحالين جميعا لكان سبيل الإنسان فيهما سبيلا واحدة، فلما لم يكن هذا هكذا وكانت القدرة في إحدى الحركتين، وجب أن تكون كسبا؛ لأن حقيقة الكسب أن الشيء وقع من المكتسب له بقوة محدثة، ولافتراق الحالين في الحركتين، ولأن إحداهما بمعنى الضرورة وجب أن تكون ضرورة، ولأن الأخرى بمعنى الكسب وجب أن تكون كسبا. ودليل الخلق كانت إحداهما خلقا أن تكون الأخرى خلقا. ألا ترى أن افتراقهما في باب الضرورة والكسب لا يوجب افتراقهما في باب الحدث والكون بعد أن لم تكونا، فكذلك لا يوجب افتراقهما في باب الحدث والكون والكسب افتراقهما في الخلق. ألا ترى أن الجسم لما لم يسبق المحدثات وجب حدوثه بدخوله في معنى الحدث، وليس يجب إذا دخل في الحدث بمشاركة المحدثات في معنى الحدث إذا كان من المحدثات ما هو "], [77, "حركة أن يكون الجسم حركة، وإذا كان منها ما هو جسم [لا] يجب أن تكون الحركة جسما، إذ لم يكونا يستويان في معنى جسم وحركة واستويا في معنى الحدوث. فكذلك لما استوى الكسب والضرورة في معنى الخلق والحدث وجب إذا كان أحدهما خلقا لله أن يكون الآخر كذلك؛ فلذلك لم يوجب افتراقهما في باب الضرورة والكسب افتراقهما في الخلق. فإن قال قائل: ما أنكرتم أن يكون الذي دل على أن إحدى الحركتين مخلوقة لله تعالى هو أن حركة الاضطرار وقعت معجزا عنها فإذا وقعت الأخرى مقدورا عليها خرجت من أن تكون مخلوقة؟ قيل له: لو كان ما وقع مقدورا لغير الله تعالى خرج من أن يكون مخلوقا لم يؤمن أن تكون حركات المرتعش من الفالج والمرتعد من الحمى إذ كان لا يستحيل عند مخالفينا أن يقدر القادر من المخلوقين على أن يفعل في غيره، فبطلت دلالتها على أن الله تعالى فعلها على ما هي عليه. وكذلك القول في حركات الأفلاك واجتماع أجزاء السماء وتأليفها. [خلقها] ولم يؤمن أن يكون لأجزاء السماء جامع غير الله سبحانه، وللأفلاك محكم، وللكواكب محرك غيره. وإذا لم يجز ذلك فقد بطل ما قالوه من أن الشيء إذا كان مقدورا لغير الله تعالى خرج من "], [78, "أن [يكون] لله تعالى مخلوقا. وأيضا فليس العجز بأن يدل على أن الله تعالى خلق المعجوز عنه بأولى من أن تكون القدرة التي جعلها الله تعالى دلالة على أ، الله خلق المقدور عليه؛ لأن ما خلق الله القدرة فينا عليه فهو عليه أقدر، كما أن [ما] خلق فينا العلم به فهو به أعلم، وما خلق فينا السمع له فهو له أسمع. فإذا استوى ذلك في قدرة الله تعالى وجب إذا أقدرنا الله تعالى على حركة الاكتساب أن يكون هو الخالق لها فينا كسبا لنا؛ لأن ما قدر عليه أن يفعله فينا ولم يفعله فينا كسبا فقد ترك أن يفعله فينا كسبا، وإذا ترك أن يكون كسبا لنا استحال أن نكون له مكتسبين؛ فدل ما قلنا على أنا لا نكتسبه إلا وقد خلقه الله تعالى لنا كسبا.\rمسألة\rفإن قال قائل: إذا كان كسب الإنسان خلقا فما أنكرت أن يكون له خالقا؟ قيل له: لم أقل إن كسبي خلق لي فيلزمني أن أكون له خالقا، وإنما قلت خلق لغيري فكيف يلزمني إذا كان خلقا لغيري أن أكون له خالقا؟ ولو كان كسبي إذا كان خلقا لله تعالى كنت له خالقا لكانت حركة المتحرك باضطرار إذا كانت خلقا لله تعالى كانت بها "], [79, "متحركا. فلما لم يجز ذلك لأنه خلقها حركة لغيره، لم يلزمنا ما قالوه؛ لأن كسبنا خلق لغيرنا.\rفإن قال: أليس قد خلق الله تعالى جور العباد؟ قيل له: خلقه جورا لهم، لا له. فإن قال: فما أنكرتم أن يكون جائرا؟ قيل له: لم يكن الجائر جائرا لأنه فعل الجور جورا لغيره لا له؛ لأ [نه] لو كان جائرا لهذه العلة لم يكن في المخلوقين جائر؛ فلما لم يكن الجائر جائرا لأنه فعل الجور جورا لغيره، لم يجب أن يكون الله بخلقه الجور جورا لغيره لا له جائرا. وأيضا فلو لزم ما قالوه لزم إذا فعل إرادة وشهوة وحركة لغيره لا له أن يكون مريدا مشتهيا متحركا؛ فلما لم يجب هذا لم يجب ما قالوه.\rفإن قالوا: فقد يخلق الله تعالى حركة لا يكتسبها أحد ولا يكون متحركا. قيل لهم: وكذلك لو خلق الله تعالى جورا لا يكتسبه أحد لم يكن به جائرا، وكان جورا لمن خلقه جورا له به يكون جائرا.\rفإن قالوا: فلم لا يقول قول غيره (كما خلق جور غيره)؟ قيل لهم: لم نقل إنه يجور [بجور] غيره، فيلزمنا أن يقول (بقول) غيره، وإنما قلنا إنه يخلق جورا لغيره لا له، ولا يكون به "], [80, "جائرا، فعروض مثل هذا أن يخلق قولا لغيره ولا يكون به قائلا. وأيضا فلو وجب أن يقول الكذب من ليس بكاذب، كما فعل الجور من ليس [بجائر، لوجب أن يقول الكذب من ليس] بكاذب كما فعل الإرادة من ليس بمريد لها، والحركة من ليس بمتحرك بها؛ فإن لم يجب هذا لم يجب ما قالوه. وأيضا فقد دللنا على أن كلام الله تعالى من صفات ذاته في صدر كتابنا هذا، فاستحال لذلك أن يكون بقول غيره قائلا، كما إذا كان العلم من صفات نفسه استحال أن يكون علم غيره علما له، وأن يكون رب العالمين عالما بعلم محدث.\rمسألة\rفإن قال قائل: فهل يخلو العبد أن يكون بين نعمة يجب عليه شكرها أو بلية يجب عليه الصبر عليها؟ قيل له: لا يخلو العبد من نعمة وبلية، والبلايا منها ما يجب الصبر عليها كالمصائب من الأمراض والأسقام، وفي الأموال والأولاد، وما أشبه ذلك. ومنها ما لا يجب الصبر عليها كالكفر وسائر المعاصي. "], [81, "مسألة\rفإن قال قائل: فهل قضي الله تعالى العاصي وقدرها؟ قيل له: نعم، بأن خلقها، وبأن كتبها وأخبر عن كونها، كما قال: {وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ فِي الْكِتَابِ} [الإسراء: 4] يعني: أخبرناهم وأعلمناهم وكما قال تعالى: {إِلَّا امْرَأَتَهُ قَدَّرْنَاهَا مِنَ الْغَابِرِينَ} [النمل: 57] يريد: كتبناها وأخبرنا أنها من الغابرين، ولا نقول قضاها وقدرها بأن أمر بها.\rفإن قال: أفقضاء الله تعالى حق؟ قيل له: من قضاء الله تعالى الذي هو خلق ما هو حق كالطاعات وما لم ينه عنه، ومن قضاء الله تعالى الذي هو خلق ما هو جور كالكفر والمعاصي؛ لأن الخلق منه حق ومنه باطل، وأما القضاء الذي هو أمر والقضاء الذي هو إعلام وإخبار وكتاب فحق؛ لأنه غير المقضي. ومن أصحابنا من يجيب بأن يقول: قضى الله المعصية والكفر ويقول بلفظ المعصية والكفر هما باطلان، ولا يقول بلفظ القضاء إنه باطل؛ لأن قول القائل قضاء الله باطل [يوهم أن قضاءه لا حقيقة له] كما يقول إذا رأى "], [82, "خشبة مكسرة بلفظ الخشبة وهي مع ذلك حجة الله تعالى، ولا يقول بلفظ الحجة إنها منكسرة؛ لأن هذا يوهم أن حجة الله تعالى لا حقيقة لها، فكذلك [يقول] إن الكفر باطل والكفر قضاء الله تعالى بمعنى أنه خلق الله، ولا يقول قضاء الله باطل؛ لأنه يوهم أن لا حقيقة لقضاء الله تعالى، وهذا كما نقول: الكافر مؤمن بالجبت والطاغوت، ولا نقول: مؤمن ونسكت؛ لما فيه من الإيهام. ونقول: النبي صلى الله عليه كافر بالجبت والطاغوت، ولا نقول كافر ونسكت لما فيه من الإيهام.\rمسألة\rفإن قال قائل: أفترضون بقضاء الله وقدره الكفر؟ قيل له: نرضى بأن قضى الله تعالى الكفر قبيحا وقدره فاسدا، ولا نرضى بأن كان الكافر به كافرا؛ لأن الله تعالى نهانا عن ذلك. وليس إذا أطلقنا الرضا بلفظ القضاء وجب أن نطلقه بلفظ الكفر، كما لا يجب إذا قلنا إن الخشبة حجة لله تعالى وإن الخشبة مكسورة أن نقول: "], [83, "حجة الله تعالى مكسورة؛ لأن هذا يوهم [أن] حجة الله تعالى لا حقيقة لها، فكذلك نطلق الرضا بلفظ القضاء والقدر، ولا نطلقه بلفظ الكفر. هذا جواب أصحابنا الذين ذكرنا جوابهم آنفا. ومن أصحابنا من يجيب بأنا نرضى بقضاء الله تعالى وقدره اللذين أمرنا أن نرضى بهما اتباعا لأمره [لأنه] لا يتقدم بين يديه ولا يعترض عليه، وهذا كما نرضى بقاء النبيين عليهم السلام ونكره موتهم، ونكره بقاء الشياطين، وكل بقضاء رب العالمين.\rمسألة\rفإن قال قائل: [فأيما خير: الخير: الخير، أو من الخير منه]؟ قيل له: من الخير منه متفضلا به فهو خير من الخير. فإن قال: فأيما شر: الشر، أو من الشر منه؟ قيل له: من كان الشر منه جائرا به فهو شر من الشر. "], [84, "مسألة\rفإن قال: أو تقولون إن الشر من الله تعالى؟ قيل له: من أصحابنا من يقول بأن الأشياء كلها من الله بالجملة، ولا يطلق بلفظ الشر أنه من الله تعالى؛ كما يقال: الأشياء كلها لله في الجملة ولا يقال على التفصيل (الزوجة والولد) لله تعالى. وكما نقول في الجملة: ما دون الله ضعيف، ولا يقال على التفصيل: دين الله ضعيف. فأما أنا فأقول: إن الشر من الله تعالى بأن خلقه شرا لغيره لا له.\rمسألة\rفإن قال: فما معنى قوله تعالى: ((يلوون ألسنتهم بالكتاب لتحسبوه من الكتاب وما هو من الكتاب ويقولون هو من عند الله وما هو من عند الل))؟ قيل له: معنى ذلك أنهم حرفوا وصف رسول الله صلى الله عليه وسلم وأوهموا السفيه منهم أنه كتابهم. قال الله تعالى: ((وما هو من الكتاب)). ((ويقولون هو من عند الله)) يعني أن الله أنزله. قال الله تعالى: ((وما هو من عند الله)) أي لم أنزل عليهم ذلك كما يدعون. "], [85, "مسألة\rفإن قال: فما معنى قوله تعالى: {مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ} [الملك: 3]؟ قيل له: قال الله تعالى: {خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا} [الملك: 3] واحدة فوق الأخرى {مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ} [الملك: 3] يعني في السموات؛ لأنه قال {فَارْجِعِ الْبَصَرَ} [الملك: 3] بعد ذكر السموات {هَلْ تَرَى مِنْ فُطُورٍ} [الملك: 3] يعني من شقوق، والكفر لا شقوق فيه. ثم قال: {ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ} [الملك: 4] في السموات والأرض {يَنْقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا} [الملك: 4] يعني معييا {وَهُوَ حَسِيرٌ} [الملك: 4] يعني مغلوبا، ولم يذكر الله تعالى الكفر ولا أفعال العباد في هذه الآية فيكون للقدرية في ذلك حجة.\rمسألة\rفإن قال قائل: فما معنى قول الله تعالى: {أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ} [السجدة: 7]؟ قيل له: معنى ذلك أنه يحسن أن يخلق، كما يقال فلان يحسن الصياغة أي يعلم كيف يصوغ، فأخبر الله تعالى أنه يعلم كيف يخلق الأشياء. "], [86, "مسألة\rفإن قال: فما معنى قوله تعالى: {وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا} [ص: 27]؟ قيل له: قال الله تعالى [بعد ذلك]: {ذَلِكَ ظَنُّ الَّذِينَ كَفَرُوا} [ص: 27] فدل ذلك على أن المعنى فيها [ما] خلقتهما وما بينهما وأنا لا أثيب من أطاعني ولا أعاقب من عصاني وكفر بي. لأن الكافرين ظنوا أنهم لا يعادون ولا لهم رجعة فيعاقبون. فبين الله تعالى أنه ما خلق الخلق إلا ومصير بعضهم إلى ثواب ورجوع بعضهم إلى العقاب، وأن الكافرين ظنوا ذلك لأنه بين أن ذلك باب الثواب والعقاب؛ لأنه تعالى قال: {أَمْ نَجْعَلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ كَالْمُفْسِدِينَ فِي الْأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجَّارِ} [ص: 28] فأخبر تعالى أن ن المشركين الذين أنكر عليهم أنهم ظنوا أنه لا عاقبة يقع فيها تفرقة بين المؤمنين والكافرين. وقد يحتمل: "], [87, "{وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا بَاطِلًا} [ص: 27] أي لم أخلق ذلك أجمع باطلا؛ لأن الباطل بعض خلق الله تعالى. ويحتمل: ما خلقت ذلك باطلا أي لم أجعله باطلا إذ خلقتهما؛ لأن الباطل حدث بعد أن خلقتهما. وقد قال الله تعالى: {خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ} [الأعراف: 54] فعموم هذا القول يدل على أنه خلق ما بينهما مما حدث من الخلق كالملائكة الذين كانوا بينهما وما خلقه بينهما من أعمال الحيوان في ذلك الوقت، فلم قضوا بإحدى الآيتين على أن الله تعالى خلق ما كان بينهما من فعل الملائكة وغيرهم في ذلك الوقت. ويقال إن كان قول الله تعالى في المشركين: {يَلْوُونَ أَلْسِنَتَهُمْ بِالْكِتَابِ لِتَحْسَبُوهُ مِنَ الْكِتَابِ وَمَا هُوَ مِنَ الْكِتَابِ وَيَقُولُونَ هُوَ مِنْ عِنْدِ اللَّهِ وَمَا هُوَ مِنْ عِنْدِ اللَّهِ} [آل عمران: 78] معناه: لم يخلقه الله فلم لا تكون الطاعات مخلوقة [له] لأنها عندكم من عند الله تعالى؟ وإن كان الكفر والمعاصي غير مخلوقة لله تعالى لأنها متفاوتة فلم لا تكون الطاعات مخلوقة له لأنها عندكم غير متفاوتة؟. وإذا كان قوله سبحانه: {أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ} [السجدة: 7] على العموم في كل شيء خلقه الله تعالى فلم لا كان قوله تعالى: {خَالِقُ "], [88, "كُلِّ شَيْءٍ} [الأنعام: 102] [على العموم] في كل شيء هو غيره؟ فإن قال: فما معنى قوله: {وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ} [الحجر: 85] قيل له: خلق الله ذلك بأن قال له: ((كن)) فالحق قوله لهما: كونا فكانتا.\rمسألة\rويقال لأهل القدر: أليس قول الله تعالى: {بِكُلِّ شَيْءٍ عَلِيمٌ} [البقرة: 29] يدل على أنه لا معلوم إلا والله به عالم فإذا قالوا: نعم. قيل لهم: ما أنكرتم أن يدل قوله تعالى: {عَلَى كُلِّ شَيْءٍ قَدِيرٌ} [البقرة: 20] على أنه لا مقدور إلا والله عليه قادر، وأن يدل قوله تعالى: ((خلق كل شيء)) على أنه لا محدث مفعول إلا والله محدث له فاعل خالق.\rمسألة\rإن سأل سائل عن قول الله تعالى: {أَنَّ اللَّهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ وَرَسُولُهُ} [التوبة: 3]. فالجواب أن الآية إنما نزلت في العهود التي كانت"], [89, "بين المشركين وبين رسول الله صلى الله عليه؛ لأن الله تعالى قال: {بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدْتُمْ مِنَ الْمُشْرِكِينَ (1) فَسِيحُوا فِي الْأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللَّهِ وَأَنَّ اللَّهَ مُخْزِي الْكَافِرِينَ} [التوبة: 1، 2]. فأجلهم الله أربعة أشهر. ثم قال: {وَأَذَانٌ مِنَ اللَّهِ وَرَسُولِهِ} [التوبة: 3] يقول وإعلام من الله ورسوله {إِلَى النَّاسِ يَوْمَ الْحَجِّ الْأَكْبَرِ أَنَّ اللَّهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ وَرَسُولُهُ} [التوبة: 3] يعني من العهود التي كانت بين رسول الله صلى الله عليه وبينهم إذا انقضت الأربعة الأشهر. ثم استثنى قوما من المشركين يقال إنهم من بني كنانة فقال: {إِلَّا الَّذِينَ عَاهَدْتُمْ عِنْدَ الْمَسْجِدِ الْحَرَامِ فَمَا اسْتَقَامُوا لَكُمْ فَاسْتَقِيمُوا لَهُمْ} [التوبة: 7] إلى انقضاء مدتهم. على أن الله تعالى ذكر المشركين ولم يقل من شركهم، ولو كان قوله تعالى: {بَرِيءٌ مِنَ الْمُشْرِكِينَ} [التوبة: 3] يدل على أنه لم يخلق شركهم لدل على أنه لم يخلقهم؛ لأنه تعالى بريء من المشركين ومن شركهم. ولو كان قوله تعالى (بريء من المشركين) يوجب أنه ما خلق شركهم للزم القدرية إذ قال إنه ولي المؤمنين أنه خلق إيمانهم. فلما لم يكن هذا عندهم هكذا بطل ما قالوه. "], [90, "مسألة\rإن قال قائل: حدثونا عن توأمين كانا في برية فوقع بقلب أحدهما أن الله واحد: من ألقى ذلك في قلبه؟ قلنا له: الله تعالى. فإن قال: أفحق ما ألقاه بقلبه؟ قيل له: نعم. فإن قال: أفصدقه فيما ألقاه بقلبه؟ قيل [له]: صدق الله تعالى لا يكون إلا كلامه، وما وقع بقلب الإنسان ليس بكلام الله تعالى فيقال إن الله تعالى صدقه فيه\rفإن قال: فإن الآخر وقع في قلبه أن الله ثالث ثلاثة: من ألقى ذلك بقلبه؟ قيل له: الله تعالى. فإن قال: أفباطل ما ألقاه بقلبه؟ قيل له: نعم. فإن قال: أفصدقه فيما القاه بقلبه أم كذبه؟ قيل [له]: خطأ أن يقال له صدقه فيه، لأن صدق الباري من صفات نفسه وهو كلامه، وخطأ أن يقال كذبه فيه، لأن الكذب لا يجوز على الباري تعالى؛ لأنه مستحيل أن يكذب، وليس يجب إذا خلق كذبا لغيره وكذبا في قلب غيره أن يكون كاذبا، كما لا يجب إذا خلق قدرة في غيره وإرادة في غيره وحركة في غيره أن يكون بذلك قادرا مريدا متحركا\rمسألة\rفإن قالوا: لم سميتمونا قدرية قيل لهم: لأنكم تزعمون في أكسابكم أنكم تقدرونها وتفعلونها مقدرة لكم دون خالقكم، والقدري هو من ينسب ذلك لنفسه، كما أن الصائغ هو من يعترف بأنه يصوغ "], [91, "دون من يزعم أنه يصاغ له، والنجار هو من يدعي أنه ينجر دون من يعترف بأنه ينجر له ولا ينجر شيئا، وكذلك القدري من يدعي أنه يفعل أفعاله مقدرة [له] دون ربه، ويزعم أن ربه لا يفعل من اكتسابه شيئا.\rفإن قال: فيلزمكم أن تكونوا قدرية لأنكم تثبتون القدر. قيل لهم: نحن نثبت أن الله تعالى قدر أعمالنا وخلقها مقدرة لنا ولا نثبت ذلك لأنفسنا، فمن أثبت القدر لله تعالى وعم أن الأفعال مقدرة لربه لا يكون قدريان كما أن من أثبت الصياغة والنجارة لغيره لا يكون صائغا ولا نجارا، ولو كنا قدرية بقولنا إن الله فعل أفعالنا مقدرة [لنا] لكانوا قدرية بقولهم إن الله تعالى فعل أفعاله كلها مقدرة له. ولو كنا بقولنا إن الله قدر المعاصي قدرية لكانوا بقولهم إن الله قدر الطاعات قدرية. فلما لم يكن ذلك كذلك بطل ما قالوه. "], [93, "(6)\rباب الكلام في الاستطاعة\r"]], "pg": [69, 93]}, "477.7": {"x": [[93, "إن قال قائل: لم قلتم إن الإنسان يستطيع باستطاعة هي غيره؟ قيل له: لأنه يكون تارة مستطيعا وتارة عاجزا، كما يكون تارة مستطيعا وتارة عاجزا، كما يكون تارة عالما وتارة غير عالم، وتارة متحركا وتارة غير متحرك، فوجب أن يكون مستطيعا بمعنى هو غيره، كما وجب أن يكون عالما بمعنى هو غيره، وكما وجب أ، يكون متحركا بمعنى هو غيره؛ لأنه لو كان مستطيعا بنفسه أو بمعنى يستحيل مفارقته له، لم يوجد إلا وهو مستطيع؛ فلما وجد مرة مستطيعا ومرة غير مستطيع صح وثبت أن استطاعته غيره.\rفإن قال قائل: فإذا أثبتم له استطاعة هي غيره فلم زعمتم أنه يستحيل تقدمها للفعل؟ قيل له: زعمنا ذلك من قبل أن الفعل لا يخلو أن يكون حادثا مع الاستطاعة في حال حدوثها أو بعدها؛ فإن كان حادثا معها في حال حدوثها فقد صح أنها مع الفعل للفعل؛ وإن كان حادثا بعدها - وقد دلت الدلالة على أنها لا تبقى - وجب حدوث الفعل بقدرة معدومة، ولو جاز ذلك لجاز أن يحدث العجز بعدها فيكون الفعل واقعا بقدرة معدومة، ولو جاز أن يفعل في حال هو "], [94, "فيها عاجز بقدرة معدومة لجاز أن يفعل بعد مائة سنة من حال حدوث القدرة وإن كان عاجزا في المائة سنة كلها بقدرة عدمت من مائة سنة وهذا فاسد. وأيضا فلو جاز حدوث الفعل مع عدم القدرة ووقع الفعل بقدرة معدومة لجاز وقوع الإحراق بحرارة نار معدومة وقد قلب الله النار بردا والقطع بحد سيف معدوم وقد قلب الله السيف قصبا، والقطع بجارحة معدومة وذلك محال؛ فإذا استحال ذلك وجب أن الفعل يحدث مع الاستطاعة في حال حدوثها.\rفإن قالوا: ولم زعمتم أن القدرة لا تبقى؟ قيل لهم: لأنها لو بقيت لكانت لا تخلو أن تبقى لنفسها أو لبقاء يقوم بها؛ فإن كانت تبقى لنفسها وجب أن تكون نفسها بقاء لها وأن لا توجد إلا باقية، وفي هذا ما يوجب أن تكون باقية في حال حدوثها. وإن كانت تبقى ببقاء يقوم بها، والبقاء صفة، فقد قامت الصفة بالصفة والعرض بالعرض، وذلك فاسد، ولو جاز أن تقوم بالصفة صفة لجاز أن تقوم بالقدرة قدرة، وبالحياة حياة، وبالعلم علم، وذلك فاسد. "], [95, "[فإن] قال: فما أنكرتم أن تكون القدرة على الشيء قدرة عليه وعلى ضده؟ قيل له: لأن من شرط القدرة المحدثة أن يكون في وجودها وجود مقدورها؛ لأن ذلك لو لم يكن من شرطها وجاز وجودها وقتا ولا مقدور، لجاز وجودها وقتين وأكثر من ذلك؛ إذ لا فرق بين وقت ووقتين وأكثر، ولو كان هذا هكذا لجاز وجودها الأبد وهو فاعل غير فاعل على وجه من الوجوه. ألا ترى أنه لما لم يكن (من شرط) قدرة القديم أن في وجودها وجود مقدورها وجاز وجودها ولا فعل، لم يستحل أن لا تزال موجودة ولا فعل على وجه من الوجوه. فلما استحال أن تكون قدرة الإنسان الأبد موجودة ولا يوجد منه فعل لا أخذ ولا ترك، ولا طاعة ولا عصيان، والأمر والنهي قائمان، استحال ذلك وقتا واحدا، وإذا استحال وقتا واحدا أن توجد القدرة ولا مقدور فقد وبج أن من شرط قدرة الإنسان أن في وجودها وجود مقدورها؛ فإذا كان ذلك استحال أن يقدر الإنسان على الشيء وضده؛ لأنه لو قدر عليهما لوجب وجودهما، وذلك محال. "], [96, "فإن قال قائل: ما أنكرتم أن تكون قدرة واحدة على إرادتين وعلى حركتين أو على مثلين؟ قيل له: إنا أنكرنا ذلك من قبل (أن) القدرة لا تكون قدرة إلا على ما يوجد معها في محلها، فلو كانت قدرة واحدة على حركتين لم يخل أن تكون قدرة على حركتين (أن) يوجدا معا في حال حدوثها، أو على حركتين أن تكون واحدة بعد أخرى. فإن كانت قدرة على حركتين أن يكونا معا فقد وجبت حركتان في موضع واحد في وقت واحد، ولو جاز هذا لجاز ارتفاع إحدى الحركتين إلى ضدها من السكون، فيكون الجوهر متحركا عن المكان ساكنا فيه في وقت واحد، وهذا المحال. وإن كانت قدرة على حركتين توجد إحداهما بعد الأخرى فقد قام الدليل والبرهان على أن القدرة لا تبقى، وهذا يوجب جواز وجود الفعل بقدرة معدومة، وهذا مما قد بينا فساده.\rومما يدل على أن الاستطاعة مع الفعل للفعل: أن من لم يخلق الله تعالى له استطاعة محال أن يكتسب شيئا، فلما استحال أن يكتسب "], [97, "الفعل إذا لم تكن استطاعة، صح أن الكسب إنما يوجد لوجودها، وفي ذلك إثبات وجودها مع الفعل للفعل.\rفإن قالوا: أليس في عدم الجارحة عدم الفعل؟ قيل لهم: في عدم الجارحة عدم القدرة، وفي عدم القدرة عدم الاكتساب؛ لأنها إذا عدمت عدمت القدرة فلعدم القدرة (ما استحال) الكسب إذا عدمت الجارحة لا لعدم الجارحة ولو عدمت الجارحة ووجدت القدرة لكان الاكتساب واقعا. ولو كان إنما استحال الاكتساب لعدم الجارحة لكانت إذا وجدت وجد الكسب؛ فلما كانت توجد ويقارنها العجز وتعدم القدرة فلا يكون كسب علم أن الاكتساب إنما لم يقع لعدم الاستطاعة لا لعدم الجارحة.\rفإن قالوا: أفليس في عدم الحياة عدم الكسب؟ قيل لهم: نعم، لأن الحياة إذا عدمت عدمت القدرة، فلعدم القدرة ما استحال الكسب، لا لعدم الحياة. ألا ترون أن الحياة تكون موجودة وثم عجز فلا يكون الإنسان مكتسبا، فعلم أن الكسب لم يعدم لعدمها ولا يوجد لوجودها. والجواب في الحياة كالجواب في الجارحة. "], [98, "فإن قالوا: إذا كان في عدم الإحسان للحياكة عدم الحياكة فلم لا يكون في وجود الإحسان لها وجودها؟ قيل [لهم] إن الحياكة تعدم لعدم قدرتها، لا لعدم إحسانها، ولو عدمت الحياكة لعدم الإحسان لها لوجدت بوجود الإحسان لها؛ فلما لم يكن ذلك كذلك وكان الإحسان لها يجامعه العجز، علم أنها إنما تعدم لعدم القدرة عليها، ولو أجرى الله تعالى العادة أن يخلق القدرة عليها مع عدم الإحسان لها لوقعت الحياكة لا محالة.\rفإن قالوا: فإذا كان في عدم التحلية والاطلاق عدم الفعل ففي وجودهما وجود الفعل. قيل لهم: كذلك نقول. فإن قالوا: فإذا كان في عدم احتمال البنية للفعل عدم الفعل فلم لا يكون في وجود احتمال البنية للشيء وجوده قيل لهم: كذلك نقول؛ لأن البنية لا تحتمل إلا ما يقوم بها.\r(وكل ما تعارضوننا) به في هذه العلة فالجواب فيه كالجواب في الجارحة والحياة؛ لأنه ليس عدم الكسب لعدمه. "], [99, "ومما يدل على أن الاستطاعة مع الفعل قول الخضر لموسى عليهما السلام: {إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا} [الكهف: 67] فعلمنا أنه لما لم يصبر لم يكن للصبر مستطيعا، وفي هذا بيان أن ما لم تكن استطاعة لم يكن الفعل وأنها إذا كانت كان لا محالة. ومما يبين ذلك أن الله تعالى قال: {مَا كَانُوا يَسْتَطِيعُونَ السَّمْعَ} [هود: 20] وقال: {وَكَانُوا لَا يَسْتَطِيعُونَ سَمْعًا} [الكهف: 101] وقد أمروا أن يسمعوا الحق وكلفوه؛ فدل ذلك على جواز تكليف ما لا يطاق وأن من لم يقبل الحق ولم يسمعه على طريق القبول لم يكن مستطيعا. فإن قالوا: ألا يستطيعون الاستقبال؟ قيل لهم: ما الفرق بينكم وبين من قال إنهم لا يستطيعون قبول الحق للاشتغال بتركه.\rمسألة\rفإن قال قائل: أليس قد كلف الله تعالى الكافر الإيمان؟ قلنا له: نعم. فإن قال: افيستطيع الإيمان؟ قيل له: لو استطاعه لآمن. فإن قال: أفكلفه ما لا يستطيع؟ قيل له: هذا كلام على أمرين: إن أردت بقولك أنه لا يستطيع الإيمان لعجزه عنه فلا، وإن أردت أنه لا يستطيعه لتركه واشتغاله بضده فنعم. فإن قال: ما أنكرتم أن يكون الله تعالى كلف الكافر ما يعجز عنه لتركه له. قيل له: العجز عن الشيء أنه يخرج عنه "], [100, "وعن ضده؛ فلذلك استحال أن يعجز العاجز عن الشيء لتركه له. فإن قال: ما أنكرت أن يكون القادر على الشيء قادرا على ضده كما كان العاجز عن الشيء عاجزا عن ضده. قيل له: لو كانت القوة على الشيء قوة على ضده قياسا على العجز للزم أن يكونا لعون على الشيء عونا على ضده قياسا على أن العجز عن الشيء عجز عن ضده. وأيضا فلو كانت القدرة على الشيء قدرة على ضده قياسا على العجز - لأن العجز عن الشيء عجز عن ضده - لوجب في القدرة ما وجب في العجز من أنه يتأتى بها الشيء وضده كما يتعذر بالعجز الشيء وضده؛ (وذلك أن) العجز إذا [وجد] عدم الشيء وضده المعجوز عنهما مع وجوده فلم يكن الإنسان مكتسبا لهما فكان يلزم في القدرة مثله إذا وجدت وهي قدرة على الشيء وضده أن يوجد الشيء وضده معها؛ لأنه يجب وجود الضدين مع وجودها، بخلاف ما يحكم به في العجز؛ لأن العجز يحكم فيه بعدم المعجوز عنه وضده مع وجوده، فإن لم يجز هذا فقد بطلت العلة وانتقضت المعارضة ولم يجب أن تقاس القدرة على العجز إذ لم تكن علة تجمع بينهما ولم تكن القدرة من جنس العجز. "], [101, "فإن قالوا: أفيجوز أن يكلف الله تعالى الشيء مع عدم الجارحة ووجود العجز؟ قيل لهم [لا]؛ لأن المأمور إنما يؤمر ليقيل أو ليترك ومع عدم الجارحة لا يوجد أخذ ولا ترك، وكذلك العجز لا يوجد معه أخذ ولا ترك، لأ (نه) عجز عن الشيء وعن ضده.\rوأيضا فلو وجب إذا أمر الله تعالى الإنسان بالشيء مع عدم قدرته أن يأمر به مع عدم القدرة كلها لوجب إذا أمر الله تعالى الإنسان مع عدم بعض العلوم وهو العلم بالله تعالى وبأنه أمر أن يأمره بالفعل مع عدم العلوم كلها فإن لم يجب هذا لم يجب إذا أمر الإنسان مع عدم القدرة على ما أمره به أن يأمر مع عدم الجارحة التي إذا عدمت عدمت القدرة كلها ومع وجود العجز الذي لم تعدم القدرة بوجوده. وكل مسألة في تكليف ما لا يطاق من الأمر بالزكاة مع عدم المال وغير ذلك من المسائل فالجواب عنه "], [102, "كما أجبت به عن سؤالهم عن الأمر مع عدم الجارحة والتكليف مع وجود العجز.\rفإن قال قائل: ما أنكرتم أن يعدم الشيء وضده لوجود عجزين؟ قيل له: لأنه [لا] نهاية لما يعجز عنه الإنسان العاجز الذي لا قدرة فيه، فلو كان العجز عن كل شيء غير العجز [عن] غيره لكان في الإنسان من الأعجاز ما لا يتناهى وهذا محال. وأيضا فإن الموت هو أكبر الأعجاز لأنه تتعذر معه الأفعال كلها، فلو كان العجز عن كل شيء غير العجز عن غيره لكان بعض الميتين إنما تعدم منه الأفعال لوجود أعجاز، وهذا يوجب أن في الجزء الواحد عجزين وموتين، ولو جاز هذا لجاز أن يرتفع أحدهما إلى حياة فيكون الجزء الواحد حيا ميتا في حال معا، وهذا محال؛ فلما استحال هذا علم أنه محال في قول من قال إن العجز عن كل شيء غير العجز عن غيره. وبالله التوفيق. "], [103, "مسألة\rفإن قال قائل: خبرونا عمن طلق امرأته وأعتق عبده: متى استطاع طلاق امرأته وعتق عبده؟ قيل له: استطاع عتق عبده في حال العتق، واستطاع طلاق امرأته في حال الطلاق. فإن قال: أفاستطاع أن يطلق من ليست امرأته وأن يعتق من ليس عبده؟ قيل له: استطاع أن يطلق من ليست امرأته في حال الطلاق وقد كانت امرأته قبل ذلك، وأن يعتق من ليس عبده في حال العتق وقد كان عبده قبل ذلك. وكذلك الجواب في إلقاء العصا والانتقال من الشمس إلى الظل وعن كسر المكسور.\rمسألة\rفإن قال قائل: خبرونا عن قول الله تعالى: {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ} [البقرة: 184]\rقيل له: يحتمل أن يكون الله تعالى أراد الذين يطيقون الإطعام ويعجزون عن الصيام عليهم الفدية إذا أفطروا، ويحتمل أن يكون أراد "], [104, "الذين يطيقون الصيام إن تكلفوه وأرادوه على قول من رجع بالهاء إلى مذكور تقدم وهو الصيام. وقد قالت المعتزلة: لا يجوز أن يرجع بها إلا إلى مذكور تقدم وهو الصيام. قيل لهم: التأويل الذي تأولناه هو تأويل بعض المتقدمين وليس النحويون حجة على الصحابة والتابعين؛ على أن كثيرا من النحويين قد أجازوا أن لا يرجع بالهاء إلى مذكور تقدم. ثم نكر على المعتزلة راجعين فنقول لهم: حدثونا عن قول الله تعالى: {هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا} [الأعراف: 189] يعني آدم وحواء {فَلَمَّا تَغَشَّاهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِ فَلَمَّا أَثْقَلَتْ} [الأعراف: 189] يعني حواء {دَعَوَا اللَّهَ رَبَّهُمَا لَئِنْ آتَيْتَنَا صَالِحًا لَنَكُونَنَّ مِنَ الشَّاكِرِينَ} [الأعراف: 189]- يريد آدم وحواء. وقوله تعالى [بعد ذلك] .. {فَلَمَّا آتَاهُمَا} [الأعراف: 190] زعمت المعتزلة أن الهاء والميم لم يرجع بهما إلى ما تقدم ذكره بل رجع "], [105, "بهما إلى المشركين من ولدهما فنقضوا قولهم إن الهاء لا يرجع بها إلا إلى مذكور قد تقدم ذكره. وقد قرأها بعض الصحابة {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ} [البقرة: 184] وكان تأويله أنهم يحملونه ولا يطيقونه.\rمسألة\rوق سألوا عن قول الله تعالى: {وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا} [آل عمران: 97]. فالجواب أن الله تعالى أراد المال وهو الزاد والراحلة، ولم يرد استطاعة البدن التي في كونها كون مقدورها، وقيام الدلالة من القياس على أن الاستطاعة مع الفعل يصح تأويلنا ويبطل تأويل مخالفينا.\rمسألة\rإن قال قائل: ما معنى قول الله تعالى: {وَسَيَحْلِفُونَ بِاللَّهِ لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ} [التوبة: 42] هل يخلو أن يكونوا كانوا مستطيعين الخروج فلم يخرجوا أو لو استطاعوا الخروج لم يخرجوا؟ فالجواب: أنهم عنوا بالاستطاعة الجدة والمال وحلفوا لرسول الله صلى الله عليه وسلم "], [106, "أنهم لا مال لهم ولا ظهر يحملون به مع نبي الله صلى الله عليه وسلم فأكذبهم الله في حلفهم، لأنهم كانوا يجدون المال؛ لم تكن المناظرة بينهم وبين رسول الله في أن الاستطاعة مع الفعل أو قبله، وإنما كانت المحاورة بينهم وبينه في الجدة والظهر. وهكذا ذكر أهل التفسير ونقلة الأخبار وحملة الآثار. وإذا كان هذا هكذا فنحن لا ننكر تقدم المال للفعل، وإنما أنكرنا تقدم استطاعة البدن للفعل.\rمسألة\rفإن سألوا عن قول الله تعالى: {فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ} [التغابن: 16] فقد يحتمل أن يكون الله تعالى أراد اتقوا الله ما كنتم مستطيعين فإن كانوا للتقوى مستطيعين كان عليهم أن يتقوا، وإن كانوا لتركه مستطيعين فعليهم أن يتقوا؛ لأن التقوى لا يلزمهم إلا أن يستطيعوه أو يستطيعوا تركه. وقد يحتمل اتقوا الله فيما استطعتم. "], [107, "مسألة\rومن سأل عن قوله تعالى: {فَمَنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا} [المجادلة: 4] فالجواب: أن من لم يستطع لعجز فعليه إطعام ستين مسكينا.\rومن سأل عن قوله تعالى: {لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا} [الطلاق: 7] فالمعنى أنه لا يكلفها من النفقة إلا ما آتاها؛ لأنه قال ذلك عقيب ذكر النفقة؛ قال: {وَمَنْ قُدِرَ عَلَيْهِ رِزْقُهُ فَلْيُنْفِقْ مِمَّا آتَاهُ اللَّهُ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا مَا آتَاهَا} [الطلاق: 7].\rومن سأل عن قوله تعالى: {لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا} [البقرة: 233] فالجواب عن ذلك أن الله تعالى لا يكلفها ما يضيق عليها من إزالة الخواطر عن النفوس التي تدعو إلى الشر؛ لأن الله تعالى قد تجاوز عن ذلك ووسع على المسلمين فيما تدعوهم نفوسهم إليه من المعصية إذا لم يرتكبوا ذل بعد أن كان ذلك مضيقا عليهم. فمعنى {لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا} [البقرة: 233] يعني إلا ما تطيقه عليها؛ لأن ما أمر الله تعالى به عباده لا يضيق عليهم فعله ولا يعجزون عن الاتيان به. وقد قال بعض أصحابنا: {لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا} [البقرة: 233] يعني إلا ما يسعها ويحل لها. "], [108, "ومن سأل عن قول الله تعالى مخبرا عن العفريت: {وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ} [النمل: 39] إن تكلفت ذلك وأردته فإن كان ممن إذا أراد ذلك أحدث الله تعالى له القدرة عليه لم يكن كاذبا، وإن لم يقل هذا القول على هذا المعنى فهو كاذب، وليس في قول العفاريت والشياطين حجة على دين رب العالمين. زعمت المعتزلة أ، العفريت لم يكذبه سليمان وهو نبي من أنبياء الله تعالى على قوله: {أَنَا آتِيكَ بِهِ قَبْلَ أَنْ تَقُومَ مِنْ مَقَامِكَ وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ} [النمل: 39]. ولا يجوز لأحد أن يكذب بين يدي نبي وهو يعلم أنه إذا كذب رد الله عليه كذبه على لسان النبي صلى الله عليه كما قال لنبيه: {إِذَا جَاءَكَ الْمُنَافِقُونَ} [المنافقون: 1] فأخبر الله تعالى بكذبهم، ومثل ذلك في القرآن "], [109, "كثير، واحتجوا بذلك أن الاستطاعة قبل الفعل. فبئس ما قالوا وظنوا بل سولت لهم أنفسهم الأباطيل. فالجواب أن نقول لمن احتج علينا بذلك: إنه ليس تخلو هذه الآية التي حكاها الله تعالى عن العفريت أن يكون العفريت عني بقوله: {وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ} [النمل: 39] إن استطعت ذلك وتكلفته وأردته، أو يكون عني بقوله: {وَإِنِّي عَلَيْهِ لَقَوِيٌّ أَمِينٌ} [النمل: 39] إن شاء الله، أو يكون عني بقوله: إن قواني الله تعالى عليه. ولو لم يعلم سليمان أن العفريت أضمر شيئا من ذلك لكذبه ورد عليه قوله. والدليل في ذلك قول الله تعالى: {فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا} [الكهف: 97] وقد جاء في التفسير: لا خلاف بين أحد من الموحدين في أنهم [كانوا] في كل يوم يأملون أن يصبحوا وقد فتحوه ولا يقولون إن شاء الله، فإذا كان المقدر قالوا: إن شاء الله فأصبحوا وقد فتحوه؛ فدل (أن لا استطاعة) لهم قبل الفعل إلا مع الفعل للفعل بإرادة الله ذلك. وقول الله تعالى في صاحب يوسف: "], [110, "{فَأَنْسَاهُ الشَّيْطَانُ ذِكْرَ رَبِّهِ فَلَبِثَ فِي السِّجْنِ بِضْعَ سِنِينَ} [يوسف: 42] أنسى الشيطان الناجي أن يذكر يوسف عند الملك فلم يكن للناجي استطاعة أن يذكر أمر يوسف للملك إذ كان قد وعد يوسف بأن يذكره عند ربه قبل خروجه م السجن، وكان ذلك لمام مراد الله تعالى بيوسف إلى الوقت المعلوم الذي رأى الملك فيه الرؤيا. وأيضا قول الله تعالى لنبيه عليه السلام: {وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَلِكَ غَدًا (23) إِلَّا أَنْ يَشَاءَ اللَّهُ} [الكهف: 23، 24] فأمر الله تعالى نبيه بأن لا يقدم على فعل شيء يقع في نفسه لم يأت أن يستثنى في قوله، وأخبر الله تعالى نبيه أن لا يكون قولك هذا كائنا قبل فعلك له [إلا] إن أردت أنا ذلك، فسلم النبي صلى الله عليه لأمر الله تعالى. وقول موسى: {رَبَّنَا اطْمِسْ عَلَى أَمْوَالِهِمْ وَاشْدُدْ عَلَى قُلُوبِهِمْ فَلَا يُؤْمِنُوا حَتَّى يَرَوُا الْعَذَابَ الْأَلِيمَ} [يونس: 88] فلم يقدروا إذ رأوا العذاب الملجئ لهم إلى الإيمان أن يؤمنوا "], [111, "ولو استطاعوا ذلك لآمنوا عند معاينتهم لأول العذاب النازل بهم. ومثل ذلك في كتاب الله كثير، وفيما دللنا به كفاية. ومثله قوله تعالى {إِلَّا قَوْمَ يُونُسَ لَمَّا آمَنُوا} [يونس: 98].\rمسألة\rومن سأل عن قول ابنة شعيب لأبيها: {يَاأَبَتِ اسْتَأْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَأْجَرْتَ الْقَوِيُّ الْأَمِينُ} [القصص: 26] فزعم الجبائي أن معنى هذه الآية أنها أخبرت عنه أنه قوي على ما يحتاج إليه أبوها من الأعمال، واستدل فيما زعم بذلك على أن الاستطاعة قبل الفعل. فما أعجزه! من أي طريق استدل بهذه الآية على هذا الفصل! وذلك أنها لم تعرف موسى من قبل قلعه للحجر الذي قلعه ونزعه بالدلو الذي نزع [به] وإنما [قالت ذلك] لما عاينت من شدته وقوته وأمانته؛ وذلك أنها لما رجعت إليه في المرة الثانية وقالت له إن أبي يدعوك، قال لها امشي أمامي واهديني الطريق، ففعلت ذلك فكانت الريح "], [112, "تصفها له فأدركت موسى عليه السلام الخشية، فقال لها: امشي خلفي وعرفيني الطريق بلسانك يمنة ويسرة وتلقاء، ففعلت ذلك، فلما جاءت إلى أبيها قالت له إنه قوي أمين، فحرد عليها حردا شديدا وقال لها: يا بنية، أما قوته فقد علمت بها لما رأيت منه فبم عرفت أمانته؟ فأخبرته بما رأت منه، فكيف علمت أنه كان مستطيعا لما [رأت منه] قبل الفعل، وإنما ظهر لها ذلك منه بعد فعله إياه؛ فصح عندنا وصحت الحجة [على] من خالفنا أن ينبغي أ، تكون استطاعته لذلك مع نفس فعله له. والدليل على ذلك من القياس أنا لو رأينا رجلا في الحال قائما يصلي لما كنا نعلم استطاعته متى حدثت له إلا أنا نعلم من نفس الفعل [أنها] ظهرت منه للفعل وهي الصلاة التي كان يفعلها. وحدتنا على من خالفنا في كل ما يورده من المسائل في باب الاستطاعة كما رسمنا فيما بينا وشرحنا، وبالله التوفيق. "], [113, "مسألة\rومن سأل عن قول الله تعالى: {وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ} [الذاريات: 56]؟ قيل له: المعنى في ذلك أنه أراد بعض الجن والإنس وهم العابدون لله منهم؛ لأن الله تعالى قال في موضع آخر {وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ} [الأعراف: 179] والقرآن لا يتناقض فوجب أن يكون الله تعالى خلق لجنهم كثيرا بالآية التي تلوناها، وأنه خلق بعضهم للعبادة بقوله: {وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ} [الذاريات: 56] والذين خلقهم لعبادته هم الذين أرادوا أن يعبدوه، وعاقبتهم عبادته.\rومن سأل عن قول الله تعالى: {مَا جَعَلَ اللَّهُ مِنْ بَحِيرَةٍ وَلَا سَائِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ} [المائدة: 103] فالمعنى أني لم أفرض عليهم ذلك ولم آمرهم به ولكنهم كذبوا على وافتروا الكذب في قولهم إني أمرتهم به.\rوالدليل على جواز تكليف ما لا يطاق من القرآن: قوله تعالى للملائكة: {أَنْبِئُونِي بِأَسْمَاءِ هَؤُلَاءِ} [البقرة: 31] يعني أسماء الخلق، وهم لا يعلمون ذلك ولا يقدرون عليه. وأيضا فقد أخبر أنهم {يُدْعَوْنَ إِلَى السُّجُودِ فَلَا يَسْتَطِيعُونَ} [القلم: 42] فإذا جاز تكليفه إياهم في الآخرة "], [114, "ما لا يطيقون جاز ذلك في الدنيا، وقد أمر الله تعالى بالعدل، وقد قال: {وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ} [النساء: 129].\rومن سأل عن قوله تعالى: {وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِلْعِبَادِ} [غافر: 31] {وَمَا اللَّهُ يُرِيدُ ظُلْمًا لِلْعَالَمِينَ} [آل عمران: 108]، فالمعنى في ذلك أنه لم يرد أن يظلمهم وإن كان أراد أن يتظالموا.\rومن سأل عن قوله تعالى: {سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللَّهُ مَا أَشْرَكْنَا وَلَا آبَاؤُنَا} [الأنعام: 148] إلى قوله {كَذَلِكَ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ} [الأنعام: 148] فالجواب: أنهم قالوا ذلك على طريق الاستهزاء ولم يقولوه على جهة الاعتقاد فأكذبهم في قولهم الذي لم يكونوا له معتقدين كما أكذب المنافقين في قولهم: {نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ} [المنافقون: 1] على طريق الاستهزاء، فقال الله تعالى: {وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ وَاللَّهُ يَشْهَدُ إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ} [المنافقون: 1].\rومن سأل عن قول الله تعالى: {يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ} [البقرة: 185] فالجواب أنه أراد أ، لا يكونوا بالإفطار في السفر والمرض حرجين ولا آثمين، وأن لا يكونوا في عسر من صيامهم "], [115, "(7)\rباب الكلام في التعديل والتجوير\r"]], "pg": [93, 115]}, "477.8": {"x": [[115, "فإن قال قائل: هل يقدر الله على لطف لو فعله بالكفار لآمنوا قيل له: نعم، والدليل على ذلك أنه يقدر أن يفعل بالمؤمنين من عباده ما لو فعله بهم لبغوا في الأرض. قال الله تعالى: {وَلَوْ بَسَطَ اللَّهُ الرِّزْقَ لِعِبَادِهِ لَبَغَوْا فِي الْأَرْضِ} [الشورى: 27] وقال: {وَلَوْلَا أَنْ يَكُونَ النَّاسُ أُمَّةً وَاحِدَةً} [الزخرف: 33] يعني على الكفر {لَجَعَلْنَا لِمَنْ يَكْفُرُ بِالرَّحْمَنِ لِبُيُوتِهِمْ سُقُفًا مِنْ فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ} [الزخرف: 33] فلما كان الله تعالى قادرا على أن يفعل بالخلق ما لو فعله بهم كفروا كان قادرا أ، يفعل بهم ما لو فعله بهم لآمنوا. وأيضا فقد دللنا على أن في كون الاستطاعة كون الفعل، فإذا كان قادرا على إقدارهم على الإيمان فهو قادر على أن يفعل ما لو فعله بهم لآمنوا.\rفإن قال: فإذا لم يفعل بالكفار ما يؤمنون عنده فقد بخل عليهم؟ قيل له: البخل أن لا يفعل الفاعل ما يجب عليه فعله، فأما ما كان "], [116, "تفضلا فللمتفضل أن يتفضل به وله أن [لا] يتفضل به، وما كان تفضلا لم يلحق البخل في أن لا يفعله الفاعل.\rفإن قالوا: فإذا لم يفعل بهم ما يؤمنون عنده فهل أراد سفههم وكفرهم؟ قيل له: نعم. وقد أوضحنا ذلك فيما سلف من كلامنا.\rمسألة\rثم يقال لهم: إن كان الله تعالى إذا لم يفعل بهم ما يؤمنون عنده يجب أن يريد فسادهم فما أنكرتم من أنه إذا خلقهم وهو يعلم أنهم يكفرون فقد أراد كفرهم؟\rفإن قالوا: مريد السفه سفيه. قيل لهم: أليس خالق من يعلم أنه يكفر لا يكون سفيها بخلقه ولا يكون خلقه إياه سفها؟ فما أنكرتم أن يكون الخالق إذا أراد سفههم لم يكن سفيها؟.\rوقد تكلمنا في هذه المسألة قبل هذا الموضع.\rمسألة\rفإن قال قائل: هل لله تعالى أن يؤلم الأطفال في الآخرة؟ قيل له: لله تعالى ذلك، وهو عادل إن فعله. وكذلك كل ما يفعله على "], [117, "جرم متناه بعقاب لا يتناهى، وتسخير الحيوان بعضهم لبعض، والإنعام على بعضهم دون بعض، وخلقه إياهم مع علمه بأنهم يكفرون كل ذلك عدل منه ولا يقبح من الله لو ابتدأهم بالعذاب الأليم وإدامته ولا يقبح منه أن يعذب المؤمنين ويدخل الكافرين الجنان، وإنما نقول إنه لا يفعل ذلك؛ لأنه أخبرنا أنه يعاقب الكافرين وهو لا يجوز عليه الكذب في خبره\rوالدليل على أن كل ما فعله فله فعله: أنه المالك القاهر الذي ليس بمملوك ولا فوقه مبيح ولا آمر ولا زاجر ولا حاظر ولا من رسم له الرسوم وحد له الحدود؛ فإذا كان هذا هكذا لم يقبح منه شيء؛ إذ كان الشيء إنما يقبح منا لأنا تجاوزنا ما حد ورسم لنا وأتينا ما لم نملك إتيانه؛ فلما لم يكن الباري مملكا ولا تحت أمر لم يقبح منه شيء. فإن قال: فإنما يقبح الكذب لأنه قبحه. قيل له: أجل ولو حسنه لكان حسنا، ولو أمر به لم يكن عليه اعتراض. فإن قالوا: فجوزوا عليه أ، يكذب كما جوزتم أن يأمر بالكذب؟ قيل لهم: ليس كل ما جاز أن يأمر به جاز أن يوصف به. ألا ترون أنه قد أمرنا أن نصلي "], [118, "ونخضع ونتحرك ولا يجوز عليه أن (يصلي ويخضع ويتحرك) لأن ذلك مستحيل عليه، وكذلك لا يجوز عليه الكذب ليس لقبحه ولكن لأنه يستحيل عليه الكذب؛ ولا يجوز أن يوصف بالقدرة على أن يكذب كما لا يجوز وصفه بالقدرة على أن (يتحرك ويجهل). ولو جاز لزاعم أن يزعم أنه يوصف الباري بالقدرة على أن يكذب ولا يوصف بالقدرة على أن يجهل ولا يأتي بين ذلك بفرقان لجاز لقالب أن يقلب القصة فيزعم أن الباري يوصف بالقدرة على أن يجهل ولا يوصف بالقدرة على أن يكذب، فلما لم يجز ذلك بطل ما قالوه.\rفإن قال قائل: إذا أمر الله أن نصلي فصلاتنا هي حركاتنا التي نتحرك [بها] إذا صلينا، والمتحرك متحرك لحلول الحركة فيه، والشاتم والكاذب إنما كان شاتما كاذبا لأنه فعل الشتم والكذب لا لأن ذلك حل فيه. يقال له: إن كانت العلة التي لها ألزمنا أن يجوز أن يكذب الباري تعالى عن ذلك علوا كبيرا أنه أمر به فيجب في كل شيء أمر به أن يجوز وصفه به؛ فإذا أمر أن نحل في أنفسنا حركات نتحرك بها، وصلاة نصلي بها، لزم أن يجوز أن يحل في نفسه "], [119, "حركات يتحرك بها وصلاة يصلي بها اللهم إلا أن يقولوا إذا جاز أن يأمر الباري غيره [بالكذب] فلم لا يجوز أن يفعل كذبا يكون به غيره كاذبا، كما إذا أمر غيره أن يصلي جاز أن يفعل لغيره صلاة يكون غيره بها مصليا. فإن سألونا عن هذا السؤال على هذا الوجه فهذا ما لا ينكر. على أنه إن كان [المصلي] مصليا لحلول الصلاة فيه كما أن المتحرك متحرك لحلول الحركة فيه فواجب أن يكون كل جزء من الإنسان [إذا حلته الصلاة] مصليا كما كان كل جزء منه إذا حلته الحركة متحركا. ويقال لهم: الصلاة في اللغة هي الدعاء، فإن [كان] المصلي مصليا لحلول الصلاة فيه فيجب أن يكون داعيا لحلول الدعاء فيه، وهذا فاسد عندهم. ثم يقال لهم: إذا جاز أن يفعل الباري تعالى صلاة لغيره ويكون بها مصليا فلم لا يفعل لغيره إرادة يكون بها مريدا، وكلاما يكون به متكلما؟ "], [120, "فإن قالوا: المتكلم المريد متكلم مريد لأنه فعل الكلام والإرادة. قيل لهم: فما أنكرتم أن يكون المصلي مصليا لأنه فعل الصلاة فيه، والمتحرك متحركا لأنه فعل الحركة فيه؟ فإن قال [قائل]: قد يتحرك منا من لا يفعل الحركة. قيل له: وقد يريد ويتكلم [منا] من لا يفعل إرادة ولا كلاما كالعاشق الذي يحب معشوقه محبة لا يمكنه الانصراف عنها، وكالذي يتكلم وهو نائم أو في حال صرعه كلاما لا يمكنه الانصراف عنه، فإن قال: ليست محبة العاشق محبة في الحقيقة، ولا إرادته إرادة. قيل لهم: وليس كلام المصروع والنائم كلاما في الحقيقة، ولا كلام اليقظان كلاما في الحقيقة، ولا إرادة العاشق إرادة في الحقيقة، وهذا ما لا يعجز عنه أحد. ثم يقال لهم: إن كان المصلي مصليا لحلول الصلاة فيه فليس الخاضع خاضعا عندكم لحلول الخضوع فيه؛ لأن الخضوع يكون في القلب والإنسان بكماله خاضع. فإن ادعوا أن القلب خاضع خاشع ألزمناهم أن يكون اللسان متكلما في الحقيقة، والقلب مريدا في الحقيقة. وإن قالوا: الخاضع لم يكن خاضعا لحلول الخضوع فيه. قيل لهم: فإذا "], [121, "أمر [نا] الله تعالى أن نخضع فيجب على قياسكم أن يخضع هو. فإن قالوا: لا، ولكنه يفعل خضوعا لغيره. قيل لهم: وكذلك إن أمرنا بالكذب فجائز أن يفعل كذبا لغيره.\rفإن قالوا: الكاذب كاذب لأنه فعل الكذب. قيل لهم مثل ذلك في الخاضع. فإن قالوا: لم يكن الخاضع خاضعا لحلول الخضوع فيه، ولا لأنه فعله. قيل لهم: ذلك في الكاذب. ثم يقال لهم: إذا أمرنا الله أن نتحرك أفليس جائزا أن يجعلنا متحركين؟ فإن قالوا: نعم. قيل لهم: وكذلك لو أمرنا بالكذب لجاز أن يجعلنا كاذبين. ثم يقال لهم: خبرونا أليس زعمتم أن الصلاة إذا كانت [كانت] حركات وكان المتحرك متحركا لحاول الحركة فيه والمصلي مصليا لحلول الصلاة فيه؟ فإن قالوا: نعم. قيل لهم: فيجب إذا أطاع الإنسان بفعل حركة أمره الله تعالى بها أن يكون طائعا لأن الطاعة حلته، كما أنه متحرك لحلول الحركة فيه؛ فإن قالوا: نعم. قيل لهم: فبعض الإنسان طائع وبعضه عاص إذا حلته المعصية، ولا بد من نعم. فيقال "], [122, "لهم: فما أنكرتم أ، يكون بعض الإنسان متكلما وهو اللسان، وبعضه عالما مريدا وهو القلب. فإن قالوا: الحركة إذا كانت طاعة فالمتحرك متحرك لحلول الحركة فيه، وليس الطائع طائعا لحلول الطاعة فيه، بل هو طائع بفعل الطاعة. قيل لهم: ما أنكرتم وإن كانت الحركات صلاة وكان المتحرك متحركا لحلول الحركة فيه فالمصلي مصل لأنه فعل الصلاة، لا لأنها حلته. فإن أجابوا إلى ذلك قيل لهم: فإذا أمرنا أن نصلي (ولم يجز أن يصلي) هو فيلزم لو أمرنا أن نكذب أن لا يجوز أن يكذب هو بل يجوز أ، يفعل لنا كذبا كما جاز أن يفعل لنا صلاة ولم يجز أ، يصلي هو، فقولوا في الكذب هذا القول. ثم يقال لهم: إذا أمرنا أن نتحرك جعل لنا حركات نتحرك بها فكذلك لو أمرنا بالكذب لم يستحل أن ي فعل لنا كذبا نكذب به. "], [123, "(8)\rباب الكلام في الإيمان\r"]], "pg": [115, 123]}, "477.9": {"x": [[123, "إن قال قائل: ما الإيمان عندكم بالله تعالى؟ قيل له: هو التصديق بالله. وعلى ذلك اجتماع أهل اللغة التي نزل بها القرآن، قال الله تعالى: {وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا بِلِسَانِ قَوْمِهِ} [إبراهيم: 4] وقال تعالى: {بِلِسَانٍ عَرَبِيٍّ مُبِينٍ} [الشعراء: 195] فلما كان الإيمان في اللغة التي أنزل الله تعالى بها القرآن هو التصديق - قال الله تعالى: {وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا وَلَوْ كُنَّا صَادِقِينَ} [يوسف: 17] أي بمصدق لنا. وقالوا جميعا: ((فلان يؤمن بعذاب القبر الشفاعة)) يريدون: يصدق بذلك - وجب أن يكون الإيمان هو ما كان عند أهل اللغة إيمانا وهو التصديق.\rفإن قال قائل: فحدثونا عن الفاسق من أهل القبلة أمؤمن هو؟ قيل له: نعم، مؤمن بإيمانه، فاسق بفسقه كبيرته. وقد أجمع أهل اللغة أن من كان منه ضرب فهو ضارب، ومن كان منه قتل فهو "], [124, "قاتل، ومن كان منه كفر فهو كافر، ومن كان منه فسق فهو فاسق، ومن كان منه تصديق فهو مصدق، وكذلك من كان منه الإيمان فهو مؤمن. ولو كان الفاسق لا مؤمنا ولا كافرا لم يكن منه كفر ولا إيمان، ولكان لا موحدا ولا ملحدا، ولا وليا ولا عدوا؛ فلما استحال ذلك استحال أن ي كون الفاسق لا مؤمنا ولا كافرا كما قالت المعتزلة. وأيضا فإذا كان الفاسق مؤمنا قبل فسقه بتوحيده فحدوث الزنا بعد التوحيد لا يبطل اسم الإيمان الذي لم يفارقه. وأيضا فقد كان الناس قبل حدوث واصل بن عطاء رئيس المعتزلة على مقالتين: منهم خوارج يكفرون مرتكبي الكبائر، ومنهم أهل استقامة يقولون هو مؤمن بإيممانه، فاسق بكبيرته، ولم يقل منهم قائل إنه ليس بمؤمن ولا كافر قبل حدوث واصل بن عطاء حتى اعتزل واصل الأمة وخرج عن قولها، فمسي معتزليا بمخالفته الإجماع (فبعد من الإجماع قوله) [وما] اتفق المسلمون عليه من أن العاصي من أهل القبلة لا يخلو من أن يكون مؤمنا أو كافرا يقضي ببطلان قوله وأيضا فلو جاز "], [125, "لقائل أن يقول: إن من معه إيمان وأتى كبيرة فليس مؤمنا بل فاسقا، لجاز لقائل أن يقول: بل هو مؤمن بإيمانه، ولا يقال فاسق بفسقه. فإن كان هذا القول مستحيلا لأنه لا يجوز فسق لا لفاسق كان قولهم مستحيلا لأنه لا يجوز إيمان لا لمؤمن. "], [127, "("]], "pg": [123, 127]}, "477.10": {"x": [[127, "9)\rباب الكلام في الخاص والعام\rوالوعد والوعيد\rإن قال قائل: خبرونا عن قول الله تعالى: {وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ} [الانفطار: 14] وعن قوله: {وَمَنْ يَفْعَلْ ذَلِكَ عُدْوَانًا وَظُلْمًا فَسَوْفَ نُصْلِيهِ نَارًا} [النساء: 30] وقوله تعالى: {إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا وَسَيَصْلَوْنَ سَعِيرًا} [النساء: 10] فالجواب عن ذلك أن قوله تعالى: {وَمَنْ يَفْعَلْ ذَلِكَ عُدْوَانًا} [النساء: 30] يحتمل أن يقع على جميع من يفعل ذلك، ويحتمل أن يقع على بعض؛ لأن لفظ ((من)) يقع في اللغة مرة على الكل ومرة على البعض، فلما كانت صورة اللفظة ترد مرة ويراد بها البعض وترد أخرى ويراد بها الكل لم يجز أن يقطع على الكل بصورتها كما لا يقطع على البعض بصورتها. وكذلك لا يقضي بقوله: {وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ} [الانفطار: 14] و {إِنَّ الَّذِينَ يَأْكُلُونَ} [النساء: 10] على بعض ولا على كل؛ إذ كان يقع ذلك تارة على الكل وتارة على البعض. ولو جاز لزاعم أن يزعم أن الصورة إنما هي للكل حتى تأتي دلالة البعض لم يكن هذا الزاعم بزعمه هذا أولى ممن قال: صورة هذا القول "], [128, "توجب القضاء على البعض إلى أن تقوم دلالة الكل. فلما تكافأ القائلان في قولهما وجب أن يكون القولان جميعا ملغيين.\rوقد قال زهير:\rومن لم يصانع في أمور كثيرة ... يضرس بأنياب ويوطأ بمنسم\rوليس كل من لا يصانع كذلك. وقال:\rومن لا يظلم الناس يظلم.\rويقول القائل: جاءني من أحببت، وإنما يعني واحدا. ويقول: جاءني التجار وإن لم يكن الكل جاءه. وجاءني جيراني، وإن لم يأت جميعهم. ويقول القائل: لقيني الفجار بما كرهت، ولا يعني جميعهم. فلما كانت هذه الألفاظ ترد مرة ويراد بها الكل وترد أخرى ويراد بها البعض، لم يجز أن يقضي على الكل دون البعض ولا على البعض دون الكل إلا بدلالة. وأيضا فلو وجب القضاء بصورة هذه الآيات أن يقضي على عذاب كل فاجر وآكل أموال اليتامى لما وآكل أموال الناس بالباطل لوجب أ، يقضي على أن كل الموحدين من أهل الصلاة في الجنة بظاهر قوله تعالى: {مَنْ "], [129, "جَاءَ بِالْحَسَنَةِ فَلَهُ خَيْرٌ مِنْهَا وَهُمْ مِنْ فَزَعٍ يَوْمَئِذٍ آمِنُونَ} [النمل: 89] وبظاهر قوله تعالى: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ} [آل عمران: 169] على أن كل مقتول في سبيل الله في الجنان يرزق فيها، وبظاهر قوله تعالى: {إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا} [الزمر: 53] على كل ذنب أنه مغفور (حتى الذنب الذي) وقف عليه الرسول صلى الله عليه وأجمع المسلمون أنه لا يغفر وهو الشرك والكفر. وليس قول من قال إن الآيات في الوعيد عامة والآيات الأخر خاصة أولى من قالب قلب القصة وجعل آيات الوعيد خاصة والآيات الأخر عامة. وأيضا فلو وجب أن يقضي بظواهر الآيات على أن كل فاجر وآكل أموال اليتامى ظلما في جهنم لجاز أن يقضي بقول الله تعالى: {كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ (8) قَالُوا بَلَى قَدْ جَاءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللَّهُ مِنْ شَيْءٍ} [الملك: 8، 9] أن النار لا يدخلها"], [130, "إلا كافر، وبظاهر قوله تعالى: {فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى (14) لَا يَصْلَاهَا إِلَّا الْأَشْقَى (15) الَّذِي كَذَّبَ وَتَوَلَّى} [الليل: 14 - 16] أن كل من يصلي النار كذلك، وبظاهر قول الله تعالى {وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ} [المائدة: 44] أنه لا يترك الحكم بما أنزل الله إلا كافر؛ فلما لم يلزم أن لا يدخل النار إلا كافر بهذه الآيات لم يلزم أن يكون كل فاجر في جهنم وكل آكل أموال اليتامى ظلما وكل من يأكل أموال الناس بالباطل في النار للآيات التي تلوناها. والجواب عن كل آية يعتلون بها في الوعيد كالجواب عن هذه الآيات. وقوله تعالى: {وَمَنْ يَفْعَلْ ذَلِكَ عُدْوَانًا وَظُلْمًا} [النساء: 30] يحتمل من يفعل ذلك مستحلا ويحتمل الجميع. وقوله: {وَإِنَّ الْفُجَّارَ لَفِي جَحِيمٍ} [الانفطار: 14] يحتمل البعض منهم وهم الكفار، ويحتمل الجميع. وكذلك الجواب عن كل آية في الوعيد. ويلزم المعتزلة أن يكون جميع أهل الشمال كافرين بظاهر قول الله تعالى: {وَأَصْحَابُ الشِّمَالِ مَا أَصْحَابُ الشِّمَالِ (41) فِي سَمُومٍ وَحَمِيمٍ (42) وَظِلٍّ مِنْ يَحْمُومٍ (43) لَا بَارِدٍ وَلَا كَرِيمٍ (44) إِنَّهُمْ كَانُوا قَبْلَ ذَلِكَ مُتْرَفِينَ (45) وَكَانُوا يُصِرُّونَ عَلَى الْحِنْثِ الْعَظِيمِ (46) وَكَانُوا "], [131, "يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ} [الواقعة: 41 - 47] وبقوله: {وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِشِمَالِهِ فَيَقُولُ يَالَيْتَنِي لَمْ أُوتَ كِتَابِيَهْ} [الحاقة: 25] إلى قوله تعالى {إِنَّهُ كَانَ لَا يُؤْمِنُ بِاللَّهِ الْعَظِيمِ (33) وَلَا يَحُضُّ عَلَى طَعَامِ الْمِسْكِينِ} [الحاقة: 33، 34]. "], [133, "(10)\rباب الكلام في الإمامة\r"]], "pg": [127, 133]}, "477.11": {"x": [[133, "إن قال قائل: ما الدليل على إمامة أبي بكر رضي الله عنه؟ قيل له: الدليل على ذلك أنا وجدنا الناس على ثلاثة أصناف: قائلين يقولون بإمامة علي بعد الرسول صلى الله عليه، وقائلين يقولون بإمامة العباس رضي الله عنه، [وقائلين يقولون بإمامة الصديق رضي الله عنه]. ورأينا عليا والعباس قد بايعاه وانقادا لأمره في كافة المسلمين وإن كان قد توقف عن البيعة متوقفون وقتا ما فقد أطبقوا على البيعة له والانقياد لإمامته والكون تحت رايته وإتباع أمره، وقالوا له: يا خليفة رسول الله، صلى الله عليه، ولا يجوز أن تجمع الأمة على خطأ. ولا يجوز لمدع أن يدعى أن باطن على والعباس بخلاف ما أظهراه، ولو جاز ذلك لم يجز لنا نقضي على صحة إجماع من الأمة على شيء [لأنا] لا نأمن أن يكون باطن بعض الأمة خلاف ظاهرهم. فلما كان بما يظهر من الأمة من الاتفاق قد يعلم به الإجماع ولا يلتفت إلى دعوى من ادعى الباطن وكان مدعى"], [134, "ذلك كقائل يقول من الخوارج إن باطن على بخلاف ظاهره؛ فلما كان في هذا إبطال الإجماع وجب القضاء على إمامة أبي بكر بعقد من عقدها له من المسلمين، وبيعة من بايعه من المهاجرين والأنصار، وإجماع المسلمين عليه في وقته، لا سيما وعلي والعباس عاقدان له البيعة على أنفسهما، ومقران له بالإمامة وخلافة الرسول صلى الله عليه. فإذا كانت الإمامة لا تخرج عن هؤلاء الثلاثة بإجماع وقد بايعاه في كافة المسلمين، وجب أن يكون إماما مفترض الطاعة. وقد نطق القرآن بإمامة الصديق ودل على إمامة الفاروق؛ وذلك أن الله تعالى قال في سورة براءة للقاعدين عن نصرة نبيه صلى الله عليه والمتخلفين عن الجهاد معه: {فَقُلْ لَنْ تَخْرُجُوا مَعِيَ أَبَدًا وَلَنْ تُقَاتِلُوا مَعِيَ عَدُوًّا إِنَّكُمْ رَضِيتُمْ بِالْقُعُودِ أَوَّلَ مَرَّةٍ فَاقْعُدُوا مَعَ الْخَالِفِينَ} [التوبة: 83] وقال في سورة أخرى: {سَيَقُولُ الْمُخَلَّفُونَ إِذَا انْطَلَقْتُمْ إِلَى مَغَانِمَ لِتَأْخُذُوهَا ذَرُونَا نَتَّبِعْكُمْ يُرِيدُونَ أَنْ يُبَدِّلُوا كَلَامَ اللَّهِ} [الفتح: 15] يعني قوله: {لَنْ تَخْرُجُوا مَعِيَ أَبَدًا وَلَنْ تُقَاتِلُوا مَعِيَ عَدُوًّا} [التوبة: 83] ثم قال (([قل لن تتبعونا] "], [135, "كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون إلا قليلا)) ثم قال: {قُلْ لِلْمُخَلَّفِينَ مِنَ الْأَعْرَابِ سَتُدْعَوْنَ إِلَى قَوْمٍ أُولِي بَأْسٍ شَدِيدٍ تُقَاتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِنْ تُطِيعُوا يُؤْتِكُمُ اللَّهُ أَجْرًا حَسَنًا} [الفتح: 16] يقول إن أطعتم الداعي لكم إلى قتالهم آتاكم تعالى أجرا حسنا)) ((وإن تتولوا)) يعني تعرضوا عن إجابة الداعي لكم إلى قتالهم ((كما توليتم من قبل)) كما أعرضتم من قبل {يُعَذِّبْكُمْ عَذَابًا أَلِيمًا} [التوبة: 39]. وقد علمنا أن الداعي لهم غير النبي صلى الله عليه؛ لأنه قال لنبيه: {فَقُلْ لَنْ تَخْرُجُوا مَعِيَ أَبَدًا} [التوبة: 83]. وقال في سورة الفتح {يُرِيدُونَ أَنْ يُبَدِّلُوا كَلَامَ اللَّهِ} [الفتح: 15] فمنعهم الله تعالى عن الخروج مع نبيه صلى الله عليه وجعل خروجهم معه تبديلا لكلامه؛ فوجب أن الداعي الذي أمروا بإتباعه داع يدعوهم بعد الرسول، وقد قال الناس قولين؛ قال بعضهم: هم فارس والروم، وقال آخرون: هم أهل اليمامة. وأبو بكر قاتل الروم وأهل اليمامة، وقوتلت فارس في أيامه وظهر بهم من بعده. فإن كانوا أهل اليمامة أو الروم فقد قاتلهم أبو بكر رضي الله عنه وفي ذلك إيجاب إمامته. وإن كانوا فارس فقد قوتلوا في أيامه وفرغ عمر منهم من بعده؛ فقد وجبت إمامة عمر، وإذا وجبت إمامة عمر وجبت إمامة أبي بكر رضي الله عنهما؛ لأن أبا بكر عقدها له. وإن "], [136, "كان المعنى: من قاتل فارس وفرغ منهم، فإذا وجبت إمامة عمر وجبت إمامة أبي بكر لأنه هو العاقد لإمامته. فدل ما قلناه من القرآن على إمامة الصديق والفاروق. وإذا وجبت إمامة أبي بكر بالدلالات التي ذكرناها - بظاهر القرآن وبإجماع المسلمين في وقته عليها - فسد قول من قال إن النبي صلى الله عليه نص على إمامة غيره؛ لأنه لا يجوز إمامة من نص الرسول على غمامة غيره، وهذا يقضي على بطلان قول من قال إن النبي صلى الله عليه نصب عليا بعده إماما.\rومما يبطل قول من قال بالنص على أبي بكر: أن أبا بكر قال لعمر: ((ابسط يدك أبا يعك)) يوم السقيفة، فلو كان رسول الله صلى الله عليه نص على إمامته لم يجز أن يقول: ((ابسط يدك أبا يعك)).\rوقد قلنا في الأبواب التي تكلمنا عليها قولا وجيزا.\r((تم الكتاب))\r(("]], "pg": [133, 136]}, "477.12": {"x": [[136, "والحمد لله رب العالمين، وصلى الله على محمد وآله وسلم))"]], "pg": [136, 136]}}, "units": {"1": {"tit": "كتاب اللمع", "lvl": 1, "pg": [1, 17]}, "2": {"tit": "الله وصفاته", "lvl": 1, "pg": [17, 33]}, "18": {"tit": "باب الكلام في القرآن والإرادة", "lvl": 1, "pg": [33, 47]}, "33": {"tit": "باب الكلام في الإرادة وأنها تعم سائر المحدثات", "lvl": 1, "pg": [47, 61]}, "47": {"tit": "باب الكلام في الرؤية", "lvl": 1, "pg": [61, 69]}, "55": {"tit": "باب الكلام في القدر", "lvl": 1, "pg": [69, 93]}, "80": {"tit": "باب الكلام في الاستطاعة", "lvl": 1, "pg": [93, 115]}, "102": {"tit": "باب الكلام في التعديل والتجوير", "lvl": 1, "pg": [115, 123]}, "110": {"tit": "باب الكلام في الإيمان", "lvl": 1, "pg": [123, 127]}, "114": {"tit": "باب الكلام في الخاص والعام والوعد والوعيد", "lvl": 1, "pg": [127, 133]}, "120": {"tit": "باب الكلام في الإمامة", "lvl": 1, "pg": [133, 136]}, "123": {"tit": "تم الكتاب", "lvl": 1, "pg": [136, 136]}}};
